/// (id, name, description) of each rule, for report rule tables.
pub(crate) const DOCS: &[(&str, &str, &str)] = &[
    ("DPI-TYP-001", "DpiTypeWidthAlignment", "Disallow 4-state types (integer, reg) in DPI-C declarations. 4-state types require complex svLogicVecVal structs in C; use 2-state portable types (int, longint, byte) for C99 ABI compatibility."),
    ("PORT-PRP-001", "ProprietaryVendorCalls", "Disallow unguarded simulator-proprietary system tasks ($vcdpluson, $fsdbDumpvars, $shm_open). Vendor-specific calls prevent Verification IP from running on other simulators."),
    ("PORT-PTH-001", "HardcodedHostPaths", "Disallow hardcoded absolute filesystem paths (/home/..., C:\\...) in file operations ($readmemh, $fopen). Absolute paths break regression execution in containerized CI/CD pipelines."),
    ("RAL-ACC-001", "DirectMirrorSetWithoutWrite", "Flags direct reg.set(...) calls that update only software mirrors without issuing physical DUT write transactions."),
    ("RAL-ACC-002", "MissingBackdoorAccessPathDefinition", "Flags RAL backdoor path configuration routines called with an empty string or null path."),
    ("RAL-ADP-001", "IncompleteRegAdapter", "Flags uvm_reg_adapter subclasses whose bus2reg() never sets rw.status or whose reg2bus() never reads rw.kind. The register layer then reports every access as passed, or turns reads into writes (adapter pattern, MG-5.1)."),
    ("RAL-BLK-001", "RegBlockNeverLocked", "Flags a top-level register block (held by an env or test, not by another block) on which lock_model() is never called. Until the model is locked, address maps are not built, so frontdoor accesses and get_reg_by_offset() fail."),
    ("RAL-COL-001", "RalAddressCollision", "Detects duplicate/overlapping address offsets mapped in uvm_reg_block address maps. Address collisions cause silent register overwriting and hardware aliasing bugs."),
    ("RAL-MAP-001", "RalOrphanRegister", "Detects instantiated uvm_reg instances inside uvm_reg_block that are never mapped via default_map.add_reg(). Orphan registers cause frontdoor access failures and verify phantom memory."),
    ("RAL-MAP-002", "RalMapAddressIntervalOverlap", "Detects 1D address interval overlaps and register aliasing collisions within the same uvm_reg_map in a uvm_reg_block, preventing silent register corruption in hardware."),
    ("RAL-WIRE-001", "RalPredictorAdapterWiring", "Verifies that all instantiated uvm_reg_predictor components have their .map property assigned in connect_phase. Without a map binding, explicit register prediction fails silently and register mirror values will never be updated during simulation."),
    ("SEC-LOG-001", "PlaintextKeyInLogs", "Detects plaintext logging of sensitive cryptographic assets (keys, seeds, secrets) via $sformatf/$display. Logging secrets compromises hardware security and violates ISO/SAE 21434 regression standards."),
    ("SV-API-001", "RefArgumentNeverWritten", "Flags ref arguments that the routine only reads; declare them const ref so callers know they are not modified (clang-tidy readability-non-const-parameter). Virtual methods are skipped because overrides share the signature."),
    ("SV-ARR-001", "OffByOneQueueIndex", "Detects out-of-bounds off-by-one queue and dynamic array indexing (e.g. 'q[q.size()]'). SystemVerilog silently returns uninitialized 'x/0 instead of raising an exception."),
    ("SV-ASC-001", "AssociativeArrayMutatingRead", "Detects direct read lookups on associative arrays in expressions without checking exists(). In SystemVerilog (IEEE 1800 § 7.8.1), reading a missing key silently allocates and inserts it with a default value."),
    ("SV-BAN-001", "LegacyRegWireInTestbench", "Discourages legacy 'reg' and 'wire' keywords in SystemVerilog testbenches in favor of 'logic'."),
    ("SV-BUG-001", "IdenticalBranches", "Flags if/else and case branches whose bodies are token-identical to an earlier branch of the same statement (clang-tidy bugprone-branch-clone, Sonar S1871)."),
    ("SV-BUG-002", "RepeatedElseIfCondition", "Flags a condition that repeats an earlier condition of the same if/else-if chain, which makes the later branch dead (Sonar S1862)."),
    ("SV-BUG-003", "SelfAssignment", "Flags 'x = x' assignments, typically a constructor or setter whose argument shadows the property it was meant to set (clang-tidy bugprone-self-assignment, Sonar S1656)."),
    ("SV-BUG-004", "MismatchedFieldInCopyCompare", "In do_copy/do_compare and similar field-wise methods, flags a field of this object paired with a differently named field of the other object when the matching field exists."),
    ("SV-BUG-005", "IntegerDivisionToReal", "Flags integer divisions whose result is used as a real value, which truncates before the conversion (Sonar S2184, SpotBugs ICAST_IDIV_CAST_TO_DOUBLE)."),
    ("SV-BUG-006", "RealEquality", "Flags == and != on real or shortreal operands, except against an exact zero (Sonar S1244, clang-tidy float equality)."),
    ("SV-BUG-007", "SuspiciousArgumentOrder", "Flags positional calls where an argument's name matches a different parameter of the callee, such as write(len, addr) for write(addr, len) (clang-tidy readability-suspicious-call-argument, Sonar S2234)."),
    ("SV-CB-001", "ClockingBlockOutputReadSkew", "Disallows reading output signals of a clocking block. Clocking block outputs are drive-only; reading them samples post-skew driven values with simulation race conditions."),
    ("SV-CMP-001", "CompilerError", "Reports the SystemVerilog compiler's errors (syntax, elaboration and type errors) as findings, so they appear in every report and in the editor next to the lint findings."),
    ("SV-CNC-002", "CircularThreadWaitDeadlock", "Detects circular lock acquisition orders and wait-for dependency cycles across concurrent threads in fork..join blocks, which cause guaranteed or probabilistic simulation deadlocks."),
    ("SV-CNC-003", "PollingLoop", "Flags loops that test a flag or signal and wait a constant #delay between tests, instead of wait(), @ or an event (busy-wait smell, Sonar S2925)."),
    ("SV-CNC-004", "SharedWriteFromForks", "Flags class properties written in two or more branches of one fork, or in a join_none thread and in its parent, without a semaphore (SpotBugs IS2_INCONSISTENT_SYNC)."),
    ("SV-CNS-001", "DefineForConstant", "Flags `define macros whose body is only a number or a string, used as constants. A package parameter or localparam has a type and a scope; a macro is global to the rest of the compilation and can be redefined silently (MG-6.1)."),
    ("SV-CNS-002", "MacroAsRoutine", "Flags multi-statement code macros that use nothing only a macro can do: no token pasting, stringification, nested macros, `__FILE__, type arguments, declarations or return/break. A function or task would be type-checked and debuggable (MG-6.1). Advisory: off by default."),
    ("SV-CNS-003", "IfdefInReusableClass", "Flags `ifdef, `ifndef and `elsif inside class bodies, apart from simulator and UVM version shims. Compile-time switches multiply the variants of a class and cannot be chosen per instance; configuration can (MG-6.1)."),
    ("SV-CNS-004", "StringAsEnum", "Flags a string variable compared against three or more literals in one case statement or if/else-if chain. The values form an enumeration the compiler cannot check; a typo in any of them fails silently (Fowler 'primitive obsession', MG-6.2). String arguments are SV-CPL-001's."),
    ("SV-CNS-005", "ManualBitFieldSlicing", "Flags a vector that is cut into three or more different fixed part-selects (hdr[7:0], hdr[15:8], hdr[31:16]). The field layout lives in scattered numbers; a packed struct names it once (MG-6.2). Advisory: off by default."),
    ("SV-CNS-006", "ImplicitEnumBaseType", "Flags enums in packages, classes and interfaces declared without a base type. They silently become 32-bit int, which wastes bits in packed items and no longer matches the width of the bus field they model (MG-6.3). Advisory: off by default."),
    ("SV-CNS-007", "LegacyIntegerType", "Flags the Verilog-1995 type 'integer' in class code. It is a 4-state 32-bit signed value; int (2-state) or an explicitly sized logic vector says what is meant (MG-6.3). Advisory: off by default."),
    ("SV-CNS-008", "FunctionOutputArguments", "Flags void class functions that hand their results back through output arguments. A return value, or a struct for several values, keeps the call an expression and makes the data flow visible (command-query separation, MG-6.3). Overrides are left alone, since their signature is fixed. Advisory: off by default."),
    ("SV-CON-004", "ConstantWaitCondition", "Flags 'wait()' statements with compile-time constant conditions (e.g., 'wait(0);', 'wait(1);'). 'wait(0);' deadlocks the simulation thread permanently, while 'wait(1);' executes instantaneously."),
    ("SV-CON-005", "SemaphoreZeroKey", "Flags semaphore method calls (sem.get(0), sem.put(0), sem.try_get(0)) passing non-positive key counts (<= 0)."),
    ("SV-CON-006", "EventTriggerInAlwaysComb", "Disallows event triggers ('->' or '->>') inside always_comb blocks (IEEE 1800 § 9.2.2.2)."),
    ("SV-CON-007", "UnboundedMailboxInstantiation", "Disallows instantiating unbounded mailboxes without a capacity limit to prevent memory bloat and missed producer-consumer synchronization."),
    ("SV-CON-008", "MutexTryGetWithoutCheck", "Flags non-blocking semaphore or mutex try_get() calls whose return status is ignored, which risks threads executing critical sections without holding the lock."),
    ("SV-CON-009", "WaitForkWithoutFork", "Flags 'wait fork;' statements in tasks or routines that contain no 'fork' blocks. Calling wait fork without spawning child processes can cause unintended hangs or dead code."),
    ("SV-CON-010", "DisableForkWithoutScope", "Disallows calling 'disable fork;' directly at task or routine scope without an enclosing isolating 'fork ... join' block."),
    ("SV-CON-011", "WaitModifiedInLoop", "Flags wait(...) statements inside loops where condition variables are never modified or assigned inside the loop body."),
    ("SV-CON-012", "ForkLoopVariableCapture", "Disallows referencing loop variables directly inside 'fork ... join_none' or 'join_any' blocks without an automatic local variable copy."),
    ("SV-CON-013", "BlockingEventTriggerInClockedBlock", "Disallows blocking event triggers (-> ev) inside clocked blocks; non-blocking triggers (->> ev) should be used instead."),
    ("SV-CON-014", "DisableNamedBlockInClass", "Flags 'disable <block>' and 'disable <task>' inside class methods. A named-block or task disable acts on every running copy, so stopping one agent's thread also stops the same thread in all other instances. 'disable fork' is not flagged."),
    ("SV-CON-015", "UnguardedBlockingWait", "Flags wait(vif.sig) and @(vif.sig) in drivers and sequences that are not raced against a timeout in fork ... join_any. Clock, reset and clocking-block events are not flagged, nor are tasks whose name says timeout or watchdog. Experimental: a watchdog elsewhere in the testbench may already cover the wait."),
    ("SV-COR-001", "TautologicalCheckCompare", "Detects tautological comparison between identical expressions (e.g. 'act_pkt.data == act_pkt.data'). Self-comparisons in scoreboards and checks always evaluate to true, masking hardware bugs."),
    ("SV-COR-005", "NonShortCircuitLogical", "Disallows using bitwise AND ('&') or bitwise OR ('|') instead of logical short-circuiting operators ('&&', '||') inside conditional statements."),
    ("SV-COR-006", "CaseWithoutDefault", "Flags 'case', 'casex', and 'casez' statements that lack an explicit 'default:' fallback branch."),
    ("SV-COR-007", "AssignmentInExpression", "Disallows assignment expressions ('=' or compound assignments) inside conditional predicates or loop conditions."),
    ("SV-COR-008", "SelfComparison", "Disallows self-comparisons where an operand is compared to itself (e.g. a == a), which tautologically evaluates to constant true or false."),
    ("SV-COR-009", "CasexProhibited", "Disallows use of 'casex' statements. 'casex' treats unknown simulation 'x' values as wildcards, masking uninitialized logic bugs and timing errors."),
    ("SV-COR-011", "ModifyingLoopIndexInsideFor", "Flags modifications to the loop control variable inside a 'for' loop body. Mutating the loop index inside the body causes infinite loops, skipped iterations, and indexing errors."),
    ("SV-COR-020", "ProceduralAssignmentAsSubExpression", "Disallows embedded assignment expressions used as sub-expressions within conditionals or arithmetic operations."),
    ("SV-COV-001", "UnreferencedCovergroup", "Detects covergroups declared in classes or modules that are never instantiated with 'new()' or never sampled. Unreferenced covergroups contribute 0 coverage samples, creating silent verification blind spots."),
    ("SV-COV-002", "ZeroWeightCoverpoint", "Flags covergroups, coverpoints, or crosses configured with option.weight or type_option.weight set to 0. Zero-weight coverage constructs collect samples but contribute 0% to regression coverage closure."),
    ("SV-COV-003", "CrossSameCoverpoint", "Detects coverage cross constructs crossing a coverpoint with itself (cross cp_a, cp_a). Crossing a coverpoint with itself creates redundant diagonal bins that distort coverage calculation."),
    ("SV-COV-004", "IllegalBinOverlap", "Detects overlapping values between regular 'bins' and 'illegal_bins' or 'ignore_bins' within a coverpoint. Per IEEE 1800 § 19.5, regular bins must not overlap with illegal or ignore bins."),
    ("SV-COV-005", "UnboundedTransitionBins", "Transition sequences in coverpoint bins must not specify unbounded repetitions (e.g., [*1:$], [->1:$]). Unbounded transition sequences cause exponential memory growth in simulator coverage databases."),
    ("SV-COV-006", "CovergroupCrossBinExplosion", "Disallows crossing 3 or more coverpoints without 'ignore_bins' or 'binsof' exclusion filters. Unfiltered multi-way crosses cause combinatorial auto-bin explosion, leading to simulator memory exhaustion."),
    ("SV-COV-007", "EmptyCovergroup", "Flags covergroups declared with zero coverpoints and zero crosses. An empty covergroup collects no coverage data."),
    ("SV-COV-008", "CrossWithEmptyBins", "Detects degenerate covergroup cross constructs specifying fewer than 2 coverpoints or empty cross products."),
    ("SV-COV-009", "CoverpointDefaultBinHazard", "Flags non-ignoring 'default' bins in coverpoints that mask uncovered stimulus and give a false sense of coverage closure."),
    ("SV-COV-010", "CrossWithAllBinsIgnored", "Flags covergroup cross constructs where all defined bins are ignore_bins, producing vacuous 0-bin coverage metrics."),
    ("SV-COV-011", "AtLeastZeroOrNegative", "Flags option.at_least or type_option.at_least set to 0 or negative values in covergroups/coverpoints. IEEE 1800 § 19.5 requires at_least to be a positive integer >= 1."),
    ("SV-COV-012", "WideCoverpointWithoutBins", "Flags coverpoints that define no explicit bins and omit option.auto_bin_max. Default auto-binning creates 64 bins, producing misleading 100% coverage closure on wide vectors."),
    ("SV-COV-013", "IgnoreBinsOverlapsIllegalBins", "Flags coverage models where the same value or range is specified in both 'ignore_bins' and 'illegal_bins' within a coverpoint."),
    ("SV-COV-014", "CoverpointWeightZero", "Flags covergroups or coverpoints where 'option.weight' or 'type_option.weight' is set to 0, silently excluding it from coverage scores."),
    ("SV-COV-015", "MissingIffOnCovergroupClock", "Covergroups sampled by a clocking event should specify an 'iff' reset guard condition."),
    ("SV-COV-016", "OverlappingRangesInCoverpointBin", "Flags coverpoint bins containing overlapping numerical value ranges."),
    ("SV-COV-017", "UnreachableCoverBin", "Flags coverpoint bins whose values all lie outside the range of the coverpoint expression (for example bins {[16:31]} on a 4-bit value). Such a bin can never be hit."),
    ("SV-CPL-001", "StringModeParameter", "Flags routines whose string argument is compared against two or more literals to choose what to do, as in do_op(\"read\"). Caller and callee must agree on spellings the compiler never checks (control coupling, connascence of meaning, MG-2.4). Use an enum argument or separate routines. Overrides are left alone."),
    ("SV-DBC-001", "InterfaceWithoutAssertions", "Flags an interface with clocking blocks or modports, so a protocol interface, that holds no assertions (assert/assume/cover property, immediate asserts, property declarations or checkers) and is not the target of a bind. Every bench that reuses it then re-checks the protocol by hand, or not at all (design by contract; MG-8.2). Advisory: off by default."),
    ("SV-DED-001", "UnusedVariable", "Local variables declared in tasks or functions should be referenced. Unused variables clutter code, consume memory, and often indicate incomplete logic."),
    ("SV-DED-002", "UnreachableStatementsPostReturn", "Detects unreachable statements appearing after an unconditional control-flow termination (return, break, continue). Dead code clutters verification environments and hides logic errors."),
    ("SV-DED-003", "AccidentalEmptyConditional", "Detects accidental semicolons immediately following if() or while() headers. An empty conditional branch causes subsequent blocks to execute unconditionally, introducing severe logic bugs."),
    ("SV-DED-004", "ConsecutiveDeadStore", "Detects consecutive assignments to the same variable where the initial value is immediately overwritten without being read. Dead stores waste CPU cycles and frequently reveal copy-paste logic bugs."),
    ("SV-DED-005", "UnreadClassProperty", "Flags class properties that are assigned or written to, but never read anywhere in the class. Unread properties indicate dead instrumentation or abandoned design state."),
    ("SV-DED-006", "UnwrittenClassProperty", "Flags non-rand class properties that lack an initializer, are read in methods, but never written or assigned. Unwritten properties always evaluate to uninitialized defaults, risking dead branches and silent logic bugs."),
    ("SV-DED-007", "UnusedPureRoutineResult", "Flags calls to pure functions or value-returning routines ($sformatf, $realtime, len, toupper, sum) used as standalone statements where the result is discarded."),
    ("SV-DED-008", "UnusedGenerateBlock", "Flags conditional statements or generate blocks with constant false conditions ('0') and no 'else' clause."),
    ("SV-DED-009", "EmptyAlwaysOrInitial", "Disallows initial, always, always_comb, always_ff, always_latch, or final procedural blocks with empty bodies."),
    ("SV-DED-010", "EmptyForkJoin", "Disallows empty fork...join, fork...join_any, or fork...join_none blocks that contain zero statements."),
    ("SV-DED-011", "EmptyTaskOrFunction", "Flags concrete, non-virtual, non-extern tasks and functions with empty bodies (zero statements). Empty routines cause useless call overhead and indicate incomplete or dead logic."),
    ("SV-DED-012", "UnreferencedParameter", "Flags parameter and localparam declarations that are never referenced within their scope or testbench. Unused parameters create clutter and indicate dead or abandoned configurations."),
    ("SV-DED-013", "UnusedRoutineArgument", "Flags task and function arguments that the body never uses (clang-tidy misc-unused-parameters, Pylint W0613). Virtual methods and overrides, phase methods, DPI routines and empty bodies are skipped."),
    ("SV-DED-014", "UnusedLocalMethod", "Flags a local task or function that no method of its class calls. A local method is invisible outside the class, so with no caller it is dead."),
    ("SV-DED-015", "NeverSetClassParameter", "Flags a parameter of a user parameterized class that no specialization in the linted design ever sets. The class claims a flexibility nobody uses or verifies (Fowler 'speculative generality'); make it a localparam or drop it. Whole-program: a specialization in a file that was not linted is not seen, and only specializations used as a class member or base class are counted. Advisory: off by default."),
    ("SV-DEP-001", "ProgramBlockDeprecation", "Disallow the obsolete SystemVerilog 'program' block. Modern verification architectures mandate 'module' with clocking blocks to prevent premature simulation termination."),
    ("SV-DEP-002", "DefparamDeprecation", "Disallow 'defparam' statements. Parameter overrides must be specified directly on instance headers."),
    ("SV-DEP-003", "LegacyAlwaysBlock", "Disallow untyped 'always' blocks. Enforces IEEE 1800 intent-specific blocks: always_comb, always_ff, or always_latch."),
    ("SV-DEP-004", "RandomSystemFunction", "Disallow legacy Verilog '$random'. Replaced by '$urandom' and '$urandom_range' in IEEE 1800."),
    ("SV-DEP-005", "ProceduralContinuousAssign", "Disallow procedural 'assign' and 'deassign' statements. Procedural continuous assignments are non-synthesizable and induce simulation race conditions."),
    ("SV-DEP-006", "NonAnsiPortList", "Disallow obsolete non-ANSI port list declarations. Enforces modern ANSI-style inline port lists."),
    ("SV-DLY-002", "IntraAssignmentDelay", "Disallows intra-assignment timing controls (e.g., a = #5 b; or a <= #5 b;) on procedural assignments. Intra-assignment delays cause simulation race conditions and are non-synthesizable."),
    ("SV-DLY-003", "RepeatLoopWithoutTiming", "Flags repeat loops inside testbench tasks that contain no time-consuming statements (#, @, wait). Zero-delay repeat loops in tasks spin instantaneously in a single delta cycle, often indicating missing clock synchronization."),
    ("SV-DLY-004", "ZeroTimeForeverLoop", "Flags forever loops whose body has no timing control, no task call and no exit, so the loop spins in zero simulation time and hangs the simulator."),
    ("SV-DRV-001", "DrivingDuringReset", "Disallow driving virtual interface control signals without an active reset check or synchronization guard. Asserting handshake signals during reset violates physical bus protocols and corrupts hardware state."),
    ("SV-DSN-001", "TypeSwitchByName", "Flags branching on get_type_name() compared with string literals instead of virtual dispatch (Sonar 'instanceof chains', open/closed principle)."),
    ("SV-DSN-002", "GodClass", "Flags classes that are very complex (WMC >= 47), use many other classes' data (ATFD > 5) and have low cohesion (TCC < 1/3): PMD's GodClass detection strategy."),
    ("SV-DSN-003", "LowCohesion", "Flags classes whose methods split into two or more groups that share no fields and do not call each other (LCOM4 > 1): the class is really several classes."),
    ("SV-DSN-004", "HighCoupling", "Flags classes other than envs and tests that reference more than 10 distinct user class types (CK coupling between objects, PMD CouplingBetweenObjects)."),
    ("SV-DSN-005", "DeepInheritance", "Flags classes with more than 3 user-defined ancestors above the UVM base class (CK depth of inheritance tree, Pylint too-many-ancestors)."),
    ("SV-DSN-006", "OverrideOnlyCallsSuper", "Flags overrides whose whole body is the super call with the same arguments, such as a connect_phase that only calls super.connect_phase(phase) (Pylint useless-parent-delegation, Sonar S1185). Constructors are kept."),
    ("SV-DSN-007", "EmptyOverrideOfConcrete", "Flags an empty override of a user base-class method that has a body, which silently switches the inherited behavior off (Fowler 'refused bequest', Liskov substitution)."),
    ("SV-DSN-008", "MutablePackageState", "Flags non-const variables declared in packages. They are shared by every env instance and test in a run (clang-tidy cppcoreguidelines-avoid-non-const-global-variables)."),
    ("SV-DSN-009", "RepeatedEnumSwitch", "Flags an enum that is switched on with case in three or more classes, a sign that behavior per kind belongs in a polymorphic item or policy class (Fowler 'repeated switches'). Advisory: off by default."),
    ("SV-DSN-010", "QueryChangesState", "Flags functions named get_*, is_* or has_* that write class properties (command-query separation). get_next_* is allowed. Advisory: off by default."),
    ("SV-DSN-011", "FeatureEnvy", "Flags a method that uses one other object's fields at least 6 times (option min_foreign) and more than twice as often as its own class's fields. The logic belongs with the data it uses (Fowler: Feature Envy; MG-3.1). Transactions, config objects, the same class and classes in the same hierarchy do not count, nor do copy/compare/print and build/connect methods. Advisory: off by default."),
    ("SV-DSN-012", "PrimitiveObsession", "Flags a rand integral field of a sequence item or config that a constraint limits to a list of 3 to 16 single constant values ('x inside {0, 1, 2}'). The field is an enumeration: as an enum it prints by name in logs and waveforms and the compiler checks every value. Advisory: off by default."),
    ("SV-DSN-013", "FatalStubOverride", "Flags an override of a user base-class method whose whole body is an error or fatal report (\"not supported here\"). The subclass refuses part of its parent's contract, so code holding a base handle fails at run time (Fowler 'refused bequest'). Split the base class instead. SV-DSN-007 covers empty overrides."),
    ("SV-DUP-001", "DuplicateMethodBody", "Detects identical or copy-pasted subroutine method bodies across different classes. Duplicated code should be refactored into shared base classes or utilities."),
    ("SV-DUP-002", "CloneFragments", "Finds runs of three or more statements (at least 50 tokens) that appear in more than one place, also when variables and literals were renamed consistently. Macro calls count as written, not as their expansion, and called names must match; runs that repeat one short cycle of statements, like unrolled loops, are left out. Each pair of routines is reported once; whole identical method bodies are SV-DUP-001's, and files whose header says they are generated are left out (DRY, Type-1/2 clones, MG-7.1)."),
    ("SV-DUP-003", "DuplicatedConstraint", "Flags a constraint body repeated in two classes that do not inherit from each other. The rule then lives in two places and drifts; declare it once in a shared base class or a policy object (Fowler 'pull up', MG-7.1). SV-RND-011 covers repeats inside one class."),
    ("SV-DUP-004", "RepeatedStringLiteral", "Flags a string literal, such as a report ID or a file name, written four or more times in the code. Config keys (UVM-CFG-008), instance names and class names are left out. One named constant keeps the copies in step (DRY, MG-7.1). Advisory: off by default."),
    ("SV-DUP-005", "CopiedAgentPackage", "Flags two packages whose classes have the same roles, fields and method bodies apart from renamed identifiers, for at least three classes and 80% of the classes in the larger package (classes with almost no code are not counted). They are one agent copied and renamed; a parameterized agent, or a shared base with small subclasses, keeps one copy to fix (DRY, MG-7.2). Advisory: off by default."),
    ("SV-DUP-006", "DataClumps", "Flags the same group of min_args (default 4) or more arguments (same names and types) declared by min_routines (default 3) or more routines. Values that always travel together belong in a transaction or struct; passing them one by one lets two same-typed arguments be swapped silently (Fowler 'data clumps'). Overrides are counted once, at the base declaration; each group is reported once, at its first routine. Advisory: off by default."),
    ("SV-ENC-001", "MutableObjectGetterLeak", "Disallows getter functions (get_*()) from returning direct references to mutable internal class object members. Returning mutable handles leaks encapsulation; return a clone or copy instead."),
    ("SV-ERR-001", "FailureNotReported", "Flags randomize(), $cast(), uvm_config_db::get(), try_* and compare() status checks whose failure branch is empty or only reports below error severity (Sonar S108/S1166)."),
    ("SV-ERR-002", "UseAfterFailedNullCheck", "Flags a handle that a null check, a failed uvm_config_db::get() or a failed $cast() showed to be null, dereferenced later on the same path because the failure branch did not stop (SpotBugs NP_NULL_ON_SOME_PATH)."),
    ("SV-ERR-003", "ProcessTerminationInClass", "Flags $finish, $stop and $exit called from class methods. The run then skips the extract, check and report phases and the UVM report summary (Sonar S1147)."),
    ("SV-EVO-001", "Hotspot", "With --history: reports the files that are both complex (summed cyclomatic complexity of their routines) and often changed in git, the top five by complexity times commits. Such hotspots are where defects collect and where refactoring pays first (Tornhill, MG-9.2). Advisory: off by default."),
    ("SV-EVO-002", "ChangeCoupling", "With --history: reports two files in different packages that change together in at least three commits and in at least half of the commits touching either. The packages have a hidden dependency that their imports do not show; move the shared knowledge to one place (temporal coupling, MG-9.2). Advisory: off by default."),
    ("SV-EVT-001", "ZeroDelayEventWaitLoop", "Using wait(event.triggered) inside a loop without an intervening time-advancing delay (@ or #) causes a zero-delay infinite delta loop that hangs the simulator at 100% CPU."),
    ("SV-FOR-001", "ForkInsideFunction", "Disallows spawning concurrent threads with 'fork ... join/join_any/join_none' inside functions. Functions must remain synchronous and instantaneous per IEEE 1800 § 13.4.4."),
    ("SV-FSM-001", "NonExhaustiveEnumCase", "Case statement switching over an enum type does not explicitly handle all declared enum variants while using a default: arm. Catch-all default arms silently swallow newly added specification states and mask FSM decoder bugs."),
    ("SV-INT-001", "BlockingAssignmentToInterface", "Disallows blocking assignments ('=') when driving virtual interface or clocking block signals. Clocking blocks and synchronous interface signals must be driven with non-blocking drives ('<=') per IEEE 1800 § 14.16."),
    ("SV-IPC-001", "TryPutIgnoredReturn", "Non-blocking IPC routines (try_put, try_get, try_peek) return a boolean status. Ignoring the return value silently drops transactions when queues are full or empty."),
    ("SV-LANG-001", "EqualityWithXz", "Detects equality ('==', '!=') checks against 4-state unknown literals ('x, 'z). Logical equality against unknowns evaluates to 'x (false in branch conditions), silently masking bugs. Use case equality ('===', '!==') instead."),
    ("SV-LANG-002", "BitSelectOutOfBounds", "Detects static out-of-bounds bit or element selects on vectors and arrays with fixed ranges. SystemVerilog silently returns 'x for out-of-bounds accesses without crashing, causing silent data corruption."),
    ("SV-LANG-003", "UnsizedLiteralInConcat", "Disallow unbased unsized integer literals inside concatenations ({1, 0, data}). Per IEEE 1800 § 11.4.12, unbased constants expand to 32 bits each, causing unintended vector widening."),
    ("SV-LANG-004", "PartSelectReversed", "Detects reversed or inverted part-select slicing on vectors (e.g. vec[0:7] on logic [7:0] vec). Part-select slicing bounds must match the declared vector endianness."),
    ("SV-LANG-005", "NonBlockingInFunction", "Prohibits non-blocking assignments ('<=') to variables inside functions: the update lands after the caller has moved on. Interface and clocking block drives are exempt (IEEE 1800 § 13.4.4 allows non-blocking assignments in functions)."),
    ("SV-LOC-001", "ArrayLocatorEmptyQueueDeref", "Disallows immediate element dereferencing on array locator methods (e.g., q.find()[0]). Locator methods return an unpacked queue that may be empty, causing out-of-bounds runtime errors (IEEE 1800 § 7.12.1)."),
    ("SV-LSP-001", "LspConstraintContradiction", "Disallows unconditionally disabling inherited constraints via '.constraint_mode(0)' in derived classes. Disabling inherited constraints breaks base class contracts and violates the Liskov Substitution Principle (LSP)."),
    ("SV-MAC-001", "HeaderMacroLeak", "Macros defined inside header files (.svh) must be undef'd with `undef before the end of the file unless registered as public API macros. Leaking macros causes silent parameter overrides and compilation collisions."),
    ("SV-MAC-002", "UnparenthesizedMacroArgument", "Flags expression macros that use an argument next to an operator without parentheses, or whose body is not wrapped in parentheses. `define DOUBLE(x) x*2 turns DOUBLE(a+1) into a+1*2; write `define DOUBLE(x) ((x)*2)."),
    ("SV-MET-001", "CognitiveComplexity", "Flags routines whose Sonar cognitive complexity (nesting-weighted branching, with fork/join counted as nesting) exceeds the threshold (default 25; Sonar S3776)."),
    ("SV-MET-002", "LongRoutine", "Flags routines with more statements than the threshold (default 100; clang-tidy readability-function-size, Checkstyle MethodLength)."),
    ("SV-MET-003", "TooManyArguments", "Flags tasks and functions with more formal arguments than the threshold (default 7; Pylint R0913, Sonar S107). Overrides are judged at the base declaration only."),
    ("SV-MET-004", "DeepNesting", "Flags routines whose control structures nest deeper than the threshold (default 5; Checkstyle NestedIfDepth, clang-tidy readability-function-size NestingThreshold)."),
    ("SV-MET-005", "ComplexCondition", "Flags conditions with more && / || operators than the threshold (default 5; Pylint R0916, Checkstyle BooleanExpressionComplexity)."),
    ("SV-MET-006", "LargeClass", "Flags classes with more than 30 properties or 30 methods; config objects and sequence items may have 80 properties, register models are exempt (PMD TooManyFields and TooManyMethods, Pylint R0902/R0904)."),
    ("SV-MET-007", "LongTask", "Flags tasks longer than the line budget (default 40 source lines, option max_lines). A long task is hard to review and to cover; split it into named tasks with one job each."),
    ("SV-MET-008", "RandFieldBudget", "Flags a sequence item that declares more than the rand-field budget (default 8, option max_rand), counting rand and randc properties of the class itself. A wide item is slow to solve and hard to constrain; split the fields across items."),
    ("SV-MET-009", "ConfigKnobBudget", "Flags a configuration object (a uvm_object named *cfg* or *config*) that declares more than max_knobs (default 12) data members of its own. Split it into per-agent or per-feature sub-configs that the parent config holds. Advisory: SV-MET-006 already allows config objects up to 80 fields, so this stricter budget is opt-in."),
    ("SV-MOD-001", "GlobalUnitPollution", "Disallow variables, nets, typedefs, tasks, and functions declared directly in the $unit compilation unit scope. Declarations outside a package or module cause cross-file namespace pollution and compile-order dependencies in multi-unit compilation."),
    ("SV-NAM-001", "UvmComponentNamingConvention", "Enforces standard naming conventions for UVM components: classes derived from uvm_driver must end with '_driver', uvm_monitor with '_monitor', uvm_agent with '_agent', uvm_env with '_env', and uvm_test with '_test'."),
    ("SV-NAM-002", "PackageNamingConvention", "Enforces that package identifiers end with '_pkg' (e.g., 'axi_pkg') to standardize namespaces."),
    ("SV-NAM-003", "InterfaceNamingConvention", "Enforces that interface identifiers end with '_if' (e.g., 'axi_if') to standardize interface definitions."),
    ("SV-NAM-005", "UvmClassTypeSuffix", "Enforces standard verification naming suffix conventions for classes extending UVM base components (e.g. _seq, _item, _driver, _monitor, _scoreboard, _env)."),
    ("SV-NAM-100", "ConfigurableNamingEngine", "Parameterizable naming convention engine validating regex, prefix, suffix, and casing conventions across packages, interfaces, UVM classes, covergroups, and constraints."),
    ("SV-OCP-001", "CastTypeInspectionLadder", "Disallows cascading $cast ladders (3+ branches) inspecting object types. Type inspection ladders violate the Open-Closed Principle (OCP); use virtual polymorphic methods instead."),
    ("SV-OOP-001", "NonVirtualMethodOverride", "Overriding a non-virtual method in a derived class breaks polymorphism when accessed via a base class handle."),
    ("SV-OOP-002", "UncheckedDynamicCast", "The return value of $cast(dest, src) must be checked (e.g., in an if statement or assert) to prevent silent null-pointer dereferences on cast failures."),
    ("SV-OOP-003", "MissingSuperNew", "Constructors in derived classes should explicitly invoke super.new(...) to ensure base class state is initialized."),
    ("SV-OOP-004", "VariableShadowing", "Detects variable shadowing where a derived class property shadows a base class property, or a method argument / local variable shadows a class member property."),
    ("SV-OOP-005", "VirtualCallInConstructor", "Never call virtual methods inside constructors. In SystemVerilog, base constructors execute before child members are initialized, resulting in child methods operating on uninitialized data."),
    ("SV-OOP-006", "ClassShallowCopyAliasing", "Using shallow copy (new other_obj) on classes containing nested object handles creates shared references across independent transactions. Use deep copy or clone() instead."),
    ("SV-OOP-007", "StaticMemberInUvmComponent", "Non-const static variable declared in a uvm_component subclass is shared across all instances simulation-wide. In multi-channel or multi-agent environments, instances will overwrite each other's state."),
    ("SV-OOP-008", "NonVirtualInterfaceInClass", "Disallows declaring physical interface types inside classes without the 'virtual' keyword (IEEE 1800 § 25.9)."),
    ("SV-OOP-009", "EmptyVirtualMethodWithoutPure", "Flags virtual methods defined with empty bodies instead of being declared 'pure virtual' in abstract base classes."),
    ("SV-OOP-010", "ClassInstantiationInLoop", "Disallows direct class instantiation via new() inside simulation loops to prevent heap contention and memory allocation overhead."),
    ("SV-OOP-011", "DowncastWithoutDynamicCast", "Flags static casting syntax (e.g. DerivedClass'(base_handle)) applied to class objects. SystemVerilog requires dynamic casting via $cast() to verify runtime polymorphism."),
    ("SV-OOP-012", "ChainedAssignmentAliasing", "Disallows chained assignment expressions (e.g. a = b = c;). Chained assignments create dangerous reference aliasing across class handles."),
    ("SV-OOP-013", "AbstractClassInstantiation", "Disallows direct instantiation of abstract (virtual) classes via 'new()'. Only concrete derived classes can be instantiated."),
    ("SV-OOP-014", "SuperNewNotFirstStatement", "Derived class constructors calling super.new(...) must invoke it as the very first procedural statement."),
    ("SV-OOP-015", "VirtualMethodSignatureMismatch", "Virtual method overrides in derived classes must match the parameter count and signature of the base virtual method."),
    ("SV-PKG-001", "FileClassNameMismatch", "Flags `include'd class files that define more than one top-level class, or whose one class is not named after the file (my_drv.svh holding my_driver). With one class per file, named after it, a class can be found from its name and reused on its own (MG-1.2)."),
    ("SV-PKG-002", "WildcardImportOutsidePackage", "Flags 'import pkg::*' at file ($unit) scope, and inside files that are `include'd into a package. Both leak names into code that never asked for them and hide where a dependency comes from (information hiding, MG-1.3)."),
    ("SV-PKG-003", "UnusedPackageImport", "Flags package imports that supply no name used in their scope. An unused import is a false dependency: the package is compiled first, changes to it look relevant, and names it exports can collide with local ones (common reuse principle, MG-1.3)."),
    ("SV-PKG-004", "PackageLayerInversion", "Flags a package that imports a package from a higher testbench layer, such as an agent package importing an env or test package. The lower package can then not be compiled or reused without the higher one (acyclic and stable dependencies, MG-1.1). UVM-ARC-001 checks the same order between classes."),
    ("SV-PKG-005", "UnstablePackageDependedOn", "Computes instability I = Ce / (Ca + Ce) for each user package from its imports and flags a package that depends on a less stable one. Many packages rely on a stable package, so its own dependencies should be at least as stable (Martin's stable dependencies principle, MG-1.4). Advisory: off by default."),
    ("SV-PRF-001", "PassArrayByValue", "Passing dynamic arrays, queues, associative arrays, unpacked arrays, or unpacked structs by value (input) causes expensive memory duplication on every call. Use 'const ref' or 'ref' instead."),
    ("SV-PRF-002", "ArrayReductionWidthTruncation", "Array reduction methods (.sum, .product) accumulate at element bit-width before extension to LHS. Summing sub-32-bit elements into 32/64-bit integers causes silent wraparound unless cast in with()."),
    ("SV-PRF-003", "DynArrayIncrementalResizeInLoop", "Growing dynamic arrays incrementally inside loops with new[arr.size()+1](arr) causes O(N^2) memory reallocation bottlenecks. Pre-allocate with new[N] or use SystemVerilog queues instead."),
    ("SV-PRF-004", "ProceduralZeroDelay", "Procedural delay #0 reschedules execution into the Inactive region. Repeated #0 rescheduling causes delta-cycle thrashing and degrades simulation throughput."),
    ("SV-PRF-005", "UnshieldedVerbosityFormatEval", "Calling $sformatf inside uvm_info/warning without checking uvm_report_enabled formats strings even when messages are discarded by verbosity."),
    ("SV-PRF-006", "StringKeyAssociativeArray", "Detects associative arrays indexed by 'string'. String keys incur hash calculation and dynamic string comparisons on every lookup and insert, degrading simulation throughput."),
    ("SV-PRF-007", "QueueConcatAppend", "Disallow queue concatenation ('q = {q, x}' or 'q = {x, q}'). Concatenation reallocates memory on every append ($O(N^2)$ in loops); use push_back() or push_front() for amortized $O(1)$ performance."),
    ("SV-PRF-008", "QueueSlicePopFirst", "Disallow queue slicing ('q = q[1:$]') to drop head elements. Queue slicing duplicates all remaining elements into new memory; use pop_front() for in-place $O(1)$ head-pointer advance."),
    ("SV-PRF-009", "NbaOnClassProperty", "Disallow non-blocking assignments ('<=') on class properties. For heap-allocated class instances, NBAs force the simulator kernel to create dynamic event descriptors in the NBA region of the event wheel. Use blocking assignment ('=')."),
    ("SV-PRF-010", "StringConcatInLoop", "Disallows iterative in-place string concatenation or $sformatf recursion inside loop bodies to prevent O(N^2) memory reallocation overhead."),
    ("SV-PRF-011", "DynamicArrayNewInLoop", "Disallows dynamic array allocation (new[...]) inside simulation loops to prevent heap contention and memory churn."),
    ("SV-PRF-012", "UnboundedDynamicArrayInConstraint", "Flags dynamic array or queue size constraints with an upper bound (< or <=) lacking an explicit lower bound."),
    ("SV-PRF-013", "ForkInClockedLoop", "Flags fork/join, join_any, and join_none inside a clocked loop (always_ff, always @(posedge/negedge), or a loop that waits on a clock edge). A thread started on every clock piles work onto the scheduler."),
    ("SV-RCE-001", "ZeroDelayEventTrigger", "Flags blocking event triggers ('-> event') which cause zero-delay simulation race conditions. Recommends non-blocking event triggers ('->> event') or persistent event evaluation ('wait(event.triggered)')."),
    ("SV-RDB-001", "PositionalFlagLiterals", "Flags calls that pass two or more 0/1 literals positionally to 1-bit arguments; use named argument binding (clang-tidy bugprone-argument-comment, Clean Code flag arguments)."),
    ("SV-RDB-002", "MagicNumber", "Flags numeric literals other than 0, 1 and -1 in class method bodies: conditions, loop bounds and sizes; delays are left to the magic-delay rules (Checkstyle MagicNumber, Sonar S109). Advisory: off by default."),
    ("SV-RDB-003", "CommentedOutCode", "Flags blocks of // comments that parse as SystemVerilog statements or declarations (Sonar S125). Advisory: off by default."),
    ("SV-RDB-004", "UndocumentedExtensionPoint", "Flags new virtual methods without a preceding comment in classes meant to be extended: classes with user subclasses, classes named *base*, and callbacks (Checkstyle MissingJavadocMethod, Pylint C0116). Advisory: off by default."),
    ("SV-RDB-005", "RedundantBoolean", "Flags 1-bit values compared with 1'b1/1'b0 and 'if (c) return 1; else return 0;' (Sonar S1125, clang-tidy readability-simplify-boolean-expr). Advisory: off by default."),
    ("SV-RDB-006", "DoubleNegativeFlag", "Flags '!' (or '~' on one bit) applied to a variable whose name is negative (disable_*, no_*, not_*, skip_*, inhibit_*, ...). Advisory: off by default."),
    ("SV-RDB-007", "NonDescriptiveName", "Flags class properties, and locals of routines longer than min_lines (default 10), named tmp, temp, val, obj, foo, d, t and the like (with or without a number; locals also data and value). Arguments and loop variables are not checked. Advisory: off by default."),
    ("SV-RDB-008", "UnclearAbbreviation", "Flags class, property, method and local names containing a vowel-less word of four or more letters (trnsfr, chnnl, rgstr) that is not a common DV short form (clk, cfg, ctrl, jtag, ...). Each person drops different vowels, so such names defeat grep. Advisory: off by default."),
    ("SV-RDB-009", "RedundantComment", "Flags a one-line // comment directly above a statement when every word of the comment (2 to 6 words, ignoring a, the, to, ...) is already a word of the statement's names, e.g. '// set cfg' above set_cfg(). Advisory: off by default."),
    ("SV-RDB-010", "UndocumentedTestbenchClass", "Flags UVM components and sequences without a comment of at least min_words (default 10) words of prose right above the class. Copyright and license lines do not count. Advisory: off by default."),
    ("SV-RND-001", "UncheckedRandomize", "The return value of randomize() must be checked. Silently ignoring failure leaves transactions un-randomized or corrupt, concealing verification testbench bugs."),
    ("SV-RND-002", "GlobalRngInClass", "Calling $urandom or $random inside class components or sequences corrupts global thread random stability. Use std::randomize() or object-scoped randomization to preserve simulation repeatability."),
    ("SV-RND-003", "RandomizeMissingSuper", "Overridden pre_randomize() and post_randomize() callback methods must invoke super.pre_randomize() or super.post_randomize() to prevent bypassing base-class transaction setup and validation routines."),
    ("SV-RND-004", "InlineShadowNoLocal", "Detects inline constraint variable shadowing inside 'randomize() with' missing 'local::'. Unqualified identifiers resolve to target object properties, turning constraints into no-op tautologies."),
    ("SV-RND-005", "NonRandFieldConstrained", "Detects class member fields that are constrained in a constraint block but not declared 'rand' or 'randc'. The solver treats non-rand fields as fixed constants and will never randomize them."),
    ("SV-RND-006", "RandcMemoryExplosion", "Disallow wide vector declarations with 'randc' (> 16 bits). Cyclic permutation tracking across large state spaces causes simulator heap exhaustion and solver startup deadlocks."),
    ("SV-RND-008", "NonInvertibleConstraintOp", "Disallow non-invertible operators (%, /, **) inside constraint blocks. Non-linear operators prevent SAT/SMT solvers from bi-directionally pruning solution spaces, causing catastrophic backtracking and long simulation stalls."),
    ("SV-RND-009", "StaticConstraint", "Disallows static constraints. Static constraints share solver state across all class instances in the simulation, causing hidden dependencies and test flakiness."),
    ("SV-RND-010", "CyclicSolveBefore", "Detects cyclic dependencies in solve...before constraint ordering (e.g. solve a before b and solve b before a). Cyclic solve-before constraints create an unsatisfiable dependency graph in the solver."),
    ("SV-RND-011", "RedundantConstraint", "Detects duplicate or redundant constraint expressions within the same class scope. Redundant constraints enlarge solver expression graphs and increase solver solve latency without adding constraints."),
    ("SV-RND-012", "ZeroWeightDistribution", "Detects constraint distribution blocks where all weights evaluate to zero. At least one weight in a distribution must evaluate to non-zero per IEEE 1800 § 18.5.4."),
    ("SV-RND-013", "UnrestoredRandMode", "Flags '.rand_mode(0)' or '.constraint_mode(0)' calls that are never restored with '1' in the routine. Unrestored disabled random modes permanently corrupt stimulus generation for subsequent transactions."),
    ("SV-RND-014", "EmptyRandomizeWith", "Flags 'randomize() with {}' containing an empty inline constraint block. Empty inline constraint blocks incur dynamic solver scope allocation overhead while adding no constraints."),
    ("SV-RND-015", "UnconstrainedRandVariable", "Flags non-static 'rand' class properties that are never constrained in any constraint block within the class."),
    ("SV-RND-016", "ConcurrentRandomizeInFork", "Disallows concurrent calls to .randomize() on the same object handle across parallel fork threads without synchronization."),
    ("SV-RND-017", "RandcStateExhaustion", "Flags 'randc' cyclic variables declared with bit-width <= 2 bits (1 or 2 bits). State permutation tables for <= 4 states reset almost immediately, incurring solver overhead with no benefit."),
    ("SV-RND-018", "RandomizeInConstructor", "Disallows calling randomize() inside class constructors (new()). Randomizing during construction breaks derived-class constraint inheritance and factory overrides."),
    ("SV-RND-019", "ConstraintImplicationMultiBit", "Flags constraint implication expressions 'A -> B' where condition 'A' is a multi-bit vector without an explicit boolean comparison."),
    ("SV-RND-020", "RandcInDynamicContainer", "Disallows declaring 'randc' cyclic variables on dynamic arrays, queues, or associative arrays (IEEE 1800 § 18.4.1)."),
    ("SV-RND-021", "ConstraintInsideInvertedRange", "Disallows inverted value ranges [low : high] where low > high in set membership expressions."),
    ("SV-RND-022", "ConstraintCallingNonPureFunction", "Functions called in constraints must be pure and must not have side effects or void return types."),
    ("SV-RND-023", "UnallocatedRandObjectArray", "Flags rand arrays of class handles whose elements are never created. randomize() sizes a dynamic array but does not construct objects, so every element stays null and its rand members are never randomized."),
    ("SV-RND-024", "RandomizeInsideAssert", "Flags randomize() used as the condition of an immediate assert or assume. Turning assertions off also skips the randomization, so the object silently keeps stale values."),
    ("SV-RND-025", "DistWideRangeColonEq", "Flags '[lo:hi] := w' in a dist when the range holds more than max_range_values (default 16) values and the dist also has items of another size. ':=' applies the weight to each value, which is rarely what the author meant; ':/' shares it."),
    ("SV-RND-026", "UnrelatedSolveBefore", "Flags 'solve a before b' when no constraint of the class (or its base classes) ties a to b, directly or through other variables. The ordering then has no effect except to suggest a dependency that does not exist."),
    ("SV-RND-027", "SoftConstraintShadowing", "Flags soft constraints whose winner is hard to predict: 'soft' inside an inline randomize() with { } block, and a soft constraint on a variable that a base class or another constraint block of the same class already constrains softly. Keep soft defaults in one place, in the base class, and override with hard constraints."),
    ("SV-RSC-001", "LockNotReleased", "Flags semaphore get()/try_get() and sequencer lock()/grab() that some path leaves without the matching put()/unlock()/ungrab(), such as an early return (Sonar S2222)."),
    ("SV-RSC-002", "FileHandleNotClosed", "Flags $fopen calls in classes that never call $fclose, which loses buffered trace data and exhausts file handles in long regressions (Sonar S2095)."),
    ("SV-SHD-002", "ForeachLoopVariableShadowing", "Flags loop index variables in 'foreach (arr[i])' loops that shadow an existing class property or routine local variable."),
    ("SV-SML-001", "ScratchpadClassProperty", "Disallow declaring scratchpad variables or loop induction counters as class properties. Move declarations to method stack frames to ensure thread safety and re-entrancy."),
    ("SV-SML-002", "MagicDelayInSequence", "Disallow hardcoded physical delays (#delay) inside uvm_sequence. Sequences must be clocking-block and frequency agnostic."),
    ("SV-SML-003", "GenericReportId", "Disallow generic single-word report IDs ('ERR', 'INFO', 'DEBUG') in UVM reporting macros. Use feature-scoped hierarchical identifiers to support precise log filtering."),
    ("SV-SML-004", "CyclomaticComplexityGodMethod", "Detects subroutines with high McCabe Cyclomatic Complexity ($M > 15$). Complex control flow obscures edge cases and inhibits functional verification."),
    ("SV-STR-001", "StreamingConcatenationSizeMismatch", "Disallows streaming concatenation operators ({>> { ... }} / {<< { ... }}) without explicit slice size. Unbounded slice streaming leads to silent truncation and byte alignment bugs per IEEE 1800 § 11.4.14."),
    ("SV-STY-001", "ClassMemberPrefix", "Enforces that member properties of uvm_component classes begin with 'm_' prefix to distinguish local member state from arguments and parameters."),
    ("SV-STY-002", "MacroTrailingSemicolon", "Flags unnecessary semicolons following `uvm_* macro invocations that create empty statements in declarative or procedural scopes."),
    ("SV-STY-003", "TodoCommentTracker", "Tracks unresolved TODO, FIXME, ICEBOX, HACK, and XXX comment markers across the codebase. Ensures temporary developer placeholders are addressed before tape-out or milestone delivery."),
    ("SV-STY-004", "TypedefNameSuffix", "Enforces naming conventions for typedefs: enums must end with '_e', and structs/data types must end with '_t'."),
    ("SV-STY-005", "MandatoryMatchingEndLabel", "Enforces explicit and matching end labels on functions, tasks, and classes (e.g., endfunction : name). Prevents scope delimiter ambiguity in large verification codebases."),
    ("SV-STY-006", "MismatchedEndLabel", "Flags mismatched end labels on functions, tasks, and classes (e.g., function void foo(); ... endfunction : bar). Prevents scope delimiter confusion and copy-paste errors."),
    ("SV-STY-007", "MethodBannerStyle", "Standardizes method separator pre-banners. Enforces 70–80 character uniform dashed separator lines and flags ragged or arbitrary-width comment separators."),
    ("SV-STY-008", "SectionHeaderBanner", "Standardizes major section divider banners to uniform 70–80 character widths. Prevents ragged ASCII banners across verification packages and testbench files."),
    ("SV-STY-009", "ExternMethodThreshold", "Enforces 'extern' declaration for class methods exceeding N lines of code (default: 5 lines). Keeps class declarations concise and readable as clean interface definitions."),
    ("SV-STY-010", "ExplicitLiteralWidth", "Disallow unsized integer and numeric literals without explicit bit-width declarations. Prevents silent 32-bit zero-extension and sign extension bugs."),
    ("SV-STY-011", "OneStatementPerLine", "Prohibit multiple procedural statements on the same line separated by semicolons. Enforces clean formatting and deterministic single-stepping in simulation debuggers."),
    ("SV-STY-012", "SpaceKeywordParen", "Requires a single space between control keywords (if, for, foreach, while, case) and opening parenthesis. Enforces common SystemVerilog code formatting guidelines."),
    ("SV-STY-013", "IncludeGuard", "Every included header file (.svh) must be wrapped in standard macro include guards (`ifndef / `define / `endif) to prevent circular definitions and compiler redefinition errors."),
    ("SV-STY-015", "TrailingWhitespace", "Disallows trailing whitespace (spaces and tabs) at the end of lines in source files."),
    ("SV-STY-016", "MaxLineLength", "Flags source lines exceeding 120 characters (option: max_columns) to preserve readability across split-view editors and terminal reviews."),
    ("SV-STY-100", "ConfigurableStyleEngine", "Parameterizable code style engine enforcing tab prohibitions, trailing whitespace limits, maximum line lengths, matching block end labels, and file naming."),
    ("SV-SVA-001", "ImmediateAssertInCombinatorialLogic", "Simple immediate assertions in always_comb or combinatorial blocks evaluate transient delta glitches. Convert to deferred immediate assertions (assert #0 or assert final) to wait for settled circuit values."),
    ("SV-SVA-002", "DisableIffComplexExpression", "Flags 'disable iff (...)' clauses containing complex boolean expressions or multi-variable logic instead of simple reset conditions."),
    ("SV-SVA-003", "MixedClockEdgesInProperty", "Flags SVA properties or assertions that mix both 'posedge' and 'negedge' clocking events."),
    ("SV-SVA-004", "NonConsecutiveRepetitionZeroBound", "Non-consecutive repetition operators ([= ...] and [-> ...]) must specify a minimum bound >= 1."),
    ("SV-SVA-005", "MultiClockConcurrentAssertionDomain", "Disallows concurrent assertions mixing multiple asynchronous clock domains without formal CDC qualification."),
    ("SV-SVA-006", "ComplexInlineProperty", "Flags assert/assume/cover property statements whose inline property uses more than max_temporal_ops (default 3) temporal operators (##, |->, |=>, [*], throughout, within, until, ...). Advisory: off by default."),
    ("SV-SYS-001", "UncheckedFopen", "Flags unchecked $fopen return descriptors and discarded $fopen calls. File operations must check whether the descriptor is valid before performing file I/O."),
    ("SV-THR-001", "ForkLoopVariableShared", "Spawning background threads with fork..join_none inside loops without copying the loop variable to an automatic local variable causes all threads to see the final loop index."),
    ("SV-THR-002", "StaticRoutineVariableLifetime", "Non-class tasks and functions default to static lifetime in SystemVerilog. Local variables in static routines share memory addresses across concurrent calls, leading to intermittent corruption."),
    ("SV-THR-003", "UnboundedThreadSpawn", "Flags fork ... join_none inside forever or while loops with no wait fork, disable fork or semaphore get in the loop to bound outstanding threads (thread-leak checks)."),
    ("SV-TIM-001", "TimescalePrecisionMismatch", "Flags `timescale directives where the time precision is coarser than the time unit (IEEE 1800 § 3.14.2)."),
    ("SV-TIM-002", "MissingTimescaleInModule", "Flags files and modules containing procedural delays (#) that lack an explicit `timescale or timeunit declaration."),
    ("SV-TST-001", "ConstantReseed", "Flags srandom() or set_randstate() with a constant in components, sequences and other non-test classes; every seed of the regression then runs the same stimulus. Advisory: off by default."),
    ("SV-TYP-001", "MixedSignComparison", "Comparing signed and unsigned integers causes implicit unsigned coercion of the signed operand. Negative values evaluate as huge positive numbers, causing comparisons to silently invert logic."),
    ("SV-TYP-008", "RedundantCastToSameType", "Flags dynamic '$cast' calls or static type casts where the source and destination already have identical static types."),
    ("SV-TYP-009", "ArrayLiteralSizeMismatch", "Flags positional array assignment patterns '{...} where the number of elements does not match the target fixed array dimension."),
    ("SV-TYP-010", "TaskWithNonVoidReturnType", "Disallows declaring tasks with explicit non-void return types."),
    ("SVA-ACT-001", "AssertWithoutElse", "Immediate and concurrent assertions must include an 'else' action block (e.g. 'else `uvm_error(...)'). Assertions without action blocks produce unhelpful one-line messages and cannot integrate with UVM reporting."),
    ("SVA-ACT-002", "TimeInAssertionAction", "Action blocks of immediate and concurrent assertions must not consume simulation time (# delays, @ event controls, or wait statements) per IEEE 1800 § 16."),
    ("SVA-ACT-003", "SideEffectInAssertionAction", "Flags assignments, increments and other writes inside the pass or fail action of an immediate or concurrent assertion. Reporting calls are fine; state changes vanish when assertions are disabled."),
    ("SVA-CTX-001", "ConcurrentAssertInFunction", "Disallow concurrent assertions ('assert/assume/cover property') inside functions. Functions execute in zero simulation time and lack clocking contexts required by SVA semantics."),
    ("SVA-CYC-001", "SvaUnboundedDelay", "Disallow unbounded cycle delays (##[1:$]) in SVA sequences. Unbounded delays cause simulator memory thread leaks and formal verification state-space explosions."),
    ("SVA-LBL-001", "UnlabeledAssertion", "Immediate and concurrent assertions must declare an explicit label prefix (e.g. 'check_lbl: assert ...'). Lacking labels makes regression failure triage, ticket routing, and assertion control commands difficult."),
    ("SVA-RST-001", "DisableIffReset", "Concurrent assertions and property declarations must include a 'disable iff (!rst_n)' clause to gate checking during power-on reset and warm resets, avoiding false-failure storms."),
    ("SVA-VAC-001", "SvaVacuousAntecedent", "Detects constant-false antecedents in assertion implications (0 |-> ...). False antecedents cause vacuous passes, giving a false 100% pass metric while never verifying DUT behavior."),
    ("UVM-ALS-001", "UvmTransactionAliasing", "Disallows in-place mutation of transaction objects after broadcasting via an analysis port (.write()). Analysis ports pass shared references; subsequent in-place mutations corrupt downstream scoreboards and subscribers."),
    ("UVM-API-001", "AccelleraOnlyApi", "Flags calls to, and classes extending, parts of the Accellera UVM library that IEEE 1800.2 does not define (tagged @uvm-accellera in the library source), such as uvm_component::print_config or uvm_port_base::debug_connected_to. Code that relies on them is tied to one UVM implementation and release. The list comes from the UVM API pack of the version being compiled."),
    ("UVM-API-002", "DeprecatedUvmMacro", "Flags uses of UVM macros that the UVM version being compiled defines only under UVM_ENABLE_DEPRECATED_API (in UVM 2020: `uvm_do_with, `uvm_do_on, `uvm_do_pri, `uvm_create_on, `uvm_send_pri and the rest of that family). Without the define the code does not compile. The list comes from the UVM API pack of the version being compiled."),
    ("UVM-ARC-001", "LayerDependency", "Flags classes that depend on a higher testbench layer (item < sequence < agent < env < test), such as a sequence that references a scoreboard or an agent that references the env (ArchUnit layer rules)."),
    ("UVM-ARC-002", "HierarchyReachThrough", "Flags expressions that reach through three or more component handles (env.agt.drv.vif), outside connect_phase wiring (PMD LawOfDemeter, Fowler 'message chains')."),
    ("UVM-ARC-003", "FileIncludedInMultiplePackages", "Flags a file whose class definitions are `include'd into more than one package. Each package gets its own, incompatible type with the same name (C++ one-definition rule)."),
    ("UVM-ARC-004", "StringHierarchyLookup", "Flags uvm_root/uvm_component find(), find_all() and lookup() calls outside tests and end_of_elaboration_phase. Looking components up by path string is a service locator that hides dependencies and breaks silently when the hierarchy changes."),
    ("UVM-BAN-001", "UvmBannedFieldMacros", "Bans the `uvm_field_* macro suite. Mandates manual do_copy, do_compare, and do_print methods to eliminate severe simulation performance overhead and uncontrollable deep copy bugs."),
    ("UVM-BAN-002", "UvmBannedUvmDoMacros", "Discourages black-box `uvm_do macros in sequence bodies. Mandates explicit start_item / finish_item transaction handshakes."),
    ("UVM-BAN-003", "DirectDoMethodCall", "Flags direct calls to do_copy, do_compare, do_print, do_pack, do_unpack and do_record. These are hooks for the public copy/compare/print/pack/record methods; calling them directly bypasses the policy object. super.do_*() inside an override is allowed."),
    ("UVM-CFG-001", "UvmConfigDbTypeMismatch", "The type parameter in uvm_config_db#(T)::get must match the type parameter used in the corresponding set call for the same field name."),
    ("UVM-CFG-002", "UvmConfigDbNullContext", "Passing 'null' as context to uvm_config_db inside a uvm_component breaks hierarchical scoping and prevents targeted configuration overrides. Use 'this' instead."),
    ("UVM-CFG-003", "UvmConfigDbGlobalWildcard", "Calling uvm_config_db::set(null, \"*\", ...) with a null context and a bare wildcard or empty scope triggers global regex matching across every component in the testbench, severely degrading simulation startup."),
    ("UVM-CFG-004", "ConfigDbGetUnchecked", "Flags calls to 'uvm_config_db#(...)::get()' where the boolean return status is ignored without being checked in an 'if' condition or assertion."),
    ("UVM-CFG-005", "ConfigDbCrossComponentResolver", "Performs cross-component semantic resolution on uvm_config_db calls across the testbench hierarchy DAG to detect configuration type mismatches between set() and get() calls."),
    ("UVM-CFG-006", "PlusargsOutsideTest", "Flags $test$plusargs, $value$plusargs and uvm_cmdline_processor reads in classes other than tests and config objects. Reading the command line deep inside components is hidden global configuration."),
    ("UVM-CFG-007", "ConfigDbAsRuntimeChannel", "Flags uvm_config_db get, set, exists and wait_modified calls in the run-time phases of components and inside loops of any task. config_db is build-time wiring; used at run time it becomes a slow global mailbox (common coupling, MG-2.3)."),
    ("UVM-CFG-008", "ScatteredConfigKeyLiteral", "Flags a uvm_config_db field name typed as a string literal in two or more files. The setter and getter only meet if both spell it the same; a shared constant makes the compiler check that (connascence of name, MG-2.4). Reported once per name."),
    ("UVM-CFG-009", "SharedConfigMutatedAtRuntime", "Flags writes to fields of a config object that the class got from uvm_config_db and did not create, made outside new() and the build phases. The object is shared by everyone who read it, so the write is hidden global state (common coupling, MG-2.3)."),
    ("UVM-CFG-010", "ConfigDbGetWithoutSet", "Flags a uvm_config_db::get whose string field name has no set in this compilation, when the compilation contains both sets and gets. Experimental: a set in a file that was not linted, or a field name built at run time, is invisible here."),
    ("UVM-CFG-011", "ConfigDbSetNeverGot", "Flags a uvm_config_db::set whose string field name has no get in this compilation, when the compilation contains both sets and gets. Experimental: a get in a file that was not linted, or a field name built at run time, is invisible here."),
    ("UVM-CPL-002", "HandleToEnvOrTest", "Flags sequences, items, agents, config objects and helpers that store a handle to a user env or test class. They then depend on everything the env contains and cannot be used under another env (stamp coupling, dependency inversion, MG-2.1)."),
    ("UVM-CPL-003", "ForeignComponentStateWrite", "Flags assignments to properties of another component through a handle, except a parent setting up its own subtree in new() and the build, connect and end_of_elaboration phases (content coupling, MG-2.1). UVM-ARC-002 covers long read chains."),
    ("UVM-CPL-004", "HierarchicalReferenceInClass", "Flags class code that names a module hierarchy (tb_top.dut.sig, $root.tb.x). Classes must reach the DUT only through virtual interfaces so they stay reusable (information hiding, MG-2.2)."),
    ("UVM-DAG-001", "UvmDanglingConfigString", "Static UVM component DAG path matching: detects glob strings in uvm_config_db::set() that match zero instantiated components in the verification hierarchy. Typographical errors in string paths cause configurations to be silently dropped."),
    ("UVM-DEP-001", "UvmDeprecatedConfigCalls", "Disallow deprecated legacy set_config_* and get_config_* methods (IEEE 1800.2 Annex H). Use type-safe uvm_config_db#(T)::set/get."),
    ("UVM-DEP-002", "UvmDeprecatedReportServer", "Disallow direct singleton calls to uvm_report_server::get_server() (IEEE 1800.2 Annex H). Obtain report servers through uvm_coreservice_t."),
    ("UVM-DEP-003", "UvmDeprecatedPrinterKnobs", "Disallow direct access to 'printer.knobs' (IEEE 1800.2 § 5.5.2). Use accessor methods on uvm_printer."),
    ("UVM-DEP-004", "UvmDeprecatedTestDone", "Disallow obsolete OVM 'uvm_test_done' objection handle (IEEE 1800.2 Annex H). Attach objections to the active phase parameter."),
    ("UVM-FAC-001", "UvmComponentDirectNew", "UVM components must be created using the UVM factory (type_name::type_id::create) instead of direct new() calls to support testbench overrides."),
    ("UVM-FAC-002", "UvmFactoryMacroMismatch", "Classes derived from uvm_component must use `uvm_component_utils, and classes derived from uvm_object (non-component) must use `uvm_object_utils."),
    ("UVM-FAC-003", "UvmFactoryMissingUtils", "Concrete classes derived from uvm_object or uvm_component must declare factory registration macros (`uvm_component_utils / `uvm_object_utils)."),
    ("UVM-FAC-004", "ParameterizedClassFactoryRegistration", "Parameterized UVM components and objects must use `uvm_component_param_utils or `uvm_object_param_utils instead of non-parameterized utils macros."),
    ("UVM-FAC-005", "GlobalFactoryOverridePollution", "Flags global factory type overrides (set_type_override, set_type_override_by_type, factory.set_type_override_by_name, T::type_id::set_type_override) outside uvm_test classes. They change the type for every test and VIP in the simulation; reusable components and sequences should use instance overrides scoped to their sub-tree."),
    ("UVM-LOG-002", "ProhibitedDisplayInUvm", "Disallow direct $display/$write/$strobe calls inside UVM classes (components, objects, sequences). SystemVerilog display tasks bypass UVM reporting infrastructure, log redirection, and verbosity filtering."),
    ("UVM-OBJ-001", "UvmUnpairedObjection", "Every phase.raise_objection() call must have a corresponding phase.drop_objection() within the same execution context to prevent simulation hangs or fatal errors."),
    ("UVM-OBJ-002", "UvmObjectionInLoop", "Avoid raising and dropping objections inside high-frequency transaction loops to prevent severe simulation performance degradation."),
    ("UVM-OBJ-003", "ObjectionControlFlowMismatch", "Performs control-flow graph (CFG) analysis on UVM phase and task routines to verify that every execution path containing raise_objection() is strictly guaranteed to reach a matching drop_objection() without early returns or asymmetric conditional branching."),
    ("UVM-OBJ-004", "OrphanSubsequenceObjectionHang", "Detects background processes launched via fork..join_none inside UVM sequences that raise objections without a deterministic drop path, leaving orphan objections that hang simulation phases."),
    ("UVM-OBJ-005", "ObjectionWithoutDescription", "Flags raise_objection()/drop_objection() on a phase or objection with no description or an empty one. A short description makes objection traces of a hung test readable."),
    ("UVM-OBS-001", "ObserverStateMutationInWrite", "Mutating the observed transaction object inside a subscriber's write() method corrupts state for other concurrent subscribers in the Observer pattern. Clone the transaction before mutating."),
    ("UVM-OBS-002", "BlockingInObserver", "Analysis write() implementations (uvm_subscriber::write and the write<SFX> methods behind uvm_analysis_imp<SFX>) must be functions that finish in zero time. Flags a write declared as a task, and a write that forks a thread per transaction."),
    ("UVM-PAT-001", "CallbackNotRegistered", "Flags `uvm_do_callbacks(T, CB, ...) in classes where no `uvm_register_cb(T, CB) registers that pair for T or a base of T. UVM then refuses to add callbacks of that type at run time, so the hook never fires (MG-5.1)."),
    ("UVM-PAT-002", "HandRolledSingleton", "Flags a class that keeps a static variable of its own type, the usual hand-rolled singleton. Every env and test in the run shares that one object, and a test cannot replace it. Pass the object through uvm_config_db or the resource database (MG-5.3)."),
    ("UVM-PAT-003", "NoExtensionPoint", "Flags a driver or monitor whose run_phase is long (25 statements or more; option min_statements) while the class and its user bases declare no virtual hook methods and use no callbacks. A test or derived agent cannot then change one step, such as error injection or timing, without copying the whole run_phase (MG-5.2). Advisory: off by default."),
    ("UVM-PHS-001", "UvmMissingSuperPhase", "Overridden standard UVM phases (e.g., build_phase, connect_phase) in uvm_component must call super.<phase_name>(phase) to ensure proper base-class configuration."),
    ("UVM-PHS-002", "UvmTimeInFunctionPhase", "Function-based UVM phases (e.g., build_phase, connect_phase) must not consume simulation time using delays (#), event controls (@), or wait statements."),
    ("UVM-PHS-003", "UvmPhaseSignatureMismatch", "Standard UVM phase methods must declare correct signatures (function void vs task, and a single argument of type uvm_phase)."),
    ("UVM-PHS-004", "SequenceInFunctionPhase", "Disallow starting sequences (.start()) inside zero-time function phases (build_phase, connect_phase, etc.). Sequences require time-consuming simulation events and must be executed in task phases."),
    ("UVM-PHS-005", "SuperBuildPhaseOrder", "Enforces that super.build_phase(phase) is the very first procedural statement in build_phase. Top-down phasing requires base class build_phase to execute before derived class configuration logic."),
    ("UVM-PHS-006", "PhaseObjectionMismatch", "Detects 'phase.raise_objection()' calls without a matching 'phase.drop_objection()' in the same task or method. Unpaired objections prevent UVM phases from terminating, causing simulation hangs."),
    ("UVM-PHS-007", "UvmPhaseJumpHazard", "Disallows manual phase jumping ('phase.jump(...)') in UVM testbenches due to objection leaks and scoreboard desynchronization risks."),
    ("UVM-PHS-008", "TimeInNonTimePhase", "Disallows time-consuming statements (#, @, wait, ##) inside non-time-consuming UVM phases (e.g. build_phase, connect_phase, check_phase)."),
    ("UVM-PHS-009", "ObjectionInNonRunPhase", "Disallows calling raise_objection() or drop_objection() inside non-run function phases (e.g. build_phase, connect_phase). Objections are strictly reserved for runtime phases."),
    ("UVM-PHS-010", "BuildPhaseCrossComponentAccess", "Detects direct access to sibling components or cross-component handles during build_phase. Because the execution order of build_phase among sibling components is undefined in UVM, referencing sibling state during build_phase results in non-deterministic initialization races."),
    ("UVM-PHS-011", "RunPhaseWithRuntimePhases", "Flags a component that overrides run_phase and also one of the runtime sub-phases (reset, configure, main, shutdown and their pre_/post_ phases). run_phase runs in parallel with all of them, so the two schedules race and readers cannot tell the order."),
    ("UVM-RAL-001", "DirectRalMirrorTampering", "Direct assignment to internal RAL fields (m_value, m_mirrored, m_desired) bypasses register callbacks, access policy checks, and prediction pipelines. Use predict() or bus operations instead."),
    ("UVM-REP-005", "LowVerbosityDebugReport", "Flags UVM debug or trace messages configured with low verbosity (UVM_LOW or UVM_NONE)."),
    ("UVM-REP-006", "BlanketErrorDemotion", "Flags report catchers that demote or swallow errors without filtering on ID or message, and severity overrides/actions that disable UVM_ERROR or UVM_FATAL for every ID (Pylint W0718 broad-exception-caught)."),
    ("UVM-REP-007", "CheckFailureAsWarning", "Flags a failed compare() or an expected-versus-actual mismatch reported only with `uvm_warning or `uvm_info. The test still passes; check failures must be errors so they are counted (MG-8.1)."),
    ("UVM-REP-008", "FatalInCheckerPath", "Flags `uvm_fatal on a data mismatch in scoreboards and subscribers. The run stops at the first mismatch and hides how many others there are; use `uvm_error and let max_quit_count stop the run (MG-8.1)."),
    ("UVM-REP-009", "InfoAtNoneVerbosity", "Flags `uvm_info messages at UVM_NONE verbosity, which cannot be filtered with +UVM_VERBOSITY. Experimental: measuring how often real benches use UVM_NONE on purpose."),
    ("UVM-ROL-001", "DriverGeneratesStimulus", "Flags drivers that randomize sequence items or start sequences. Stimulus belongs in sequences, where tests can layer constraints and the sequencer can arbitrate; a driver only converts items to pin activity (single responsibility, MG-3.1)."),
    ("UVM-ROL-002", "CoverageOutsideObservers", "Flags covergroups declared in drivers and sequences. They sample what was intended, not what reached the DUT, and disappear when the agent is passive; collect coverage in a monitor or subscriber (MG-3.1)."),
    ("UVM-ROL-003", "DutCheckingInAgent", "Flags agents that hold a scoreboard, predictor or reference model. Agents carry protocol knowledge only; DUT-specific checking belongs in the env so the agent can be reused with other DUTs (MG-3.2)."),
    ("UVM-ROL-004", "TestBuildsLeafComponents", "Flags tests that create drivers, monitors, sequencers, agents, scoreboards or subscribers directly. Tests configure and select; the env builds, so every test shares one structure (facade, MG-3.3)."),
    ("UVM-ROL-005", "MonitorDependsOnActivePath", "Flags monitors that hold a handle to a driver, sequencer or sequence item port. A monitor must work on its own, observing only the interface, or it breaks in passive agents (MG-3.1)."),
    ("UVM-ROL-006", "VirtualInterfaceInChecker", "Flags virtual interface handles in scoreboards and subscribers. Pin timing belongs in drivers, monitors and interface assertions; a checker that waits on signals cannot run against a transaction-level model or an emulator, and hides a second monitor. Sequences are covered by UVM-SEQ-001."),
    ("UVM-ROL-007", "ProceduralTimeoutInMonitor", "Flags fork ... join_any blocks in a monitor where one branch counts clock cycles (repeat (N) @(...)) and then reports an error: a handshake timeout written as procedural code. A concurrent assertion in the interface states the same rule in one line and checks it every cycle. Advisory: off by default."),
    ("UVM-RUS-001", "AgentIgnoresIsActive", "Flags agents that create their driver or sequencer without checking is_active or get_is_active(). Such an agent cannot be reused as a passive monitor in a larger env (MG-4.1)."),
    ("UVM-RUS-002", "AgentWithoutConfigObject", "Flags agents and envs that read three or more separate scalar settings from uvm_config_db instead of one config object (Fowler 'data clumps', MG-4.2)."),
    ("UVM-RUS-003", "HardcodedTopology", "Flags envs that create components in a loop with a literal count instead of a count from their config object (open/closed principle, MG-4.2)."),
    ("UVM-RUS-004", "AbsoluteConfigDbPath", "Flags uvm_config_db calls in classes whose path starts at uvm_test_top. Below the test the path should be relative to 'this'; with a non-null context an absolute path is appended to the context and never matches (MG-4.3)."),
    ("UVM-RUS-005", "OverrideByNameString", "Flags factory overrides and creates that name types with string literals (set_type_override_by_name, set_inst_override, create_object ...). A typo or rename is only found at run time; T::type_id::set_type_override() is checked by the compiler (connascence of name, MG-4.3)."),
    ("UVM-RUS-006", "IncompleteItemContract", "Flags concrete sequence items with fields that implement neither field macros nor do_copy(), do_compare() and convert2string()/do_print(). Scoreboards, clone() and debug prints then silently see default behaviour (MG-4.4)."),
    ("UVM-SCB-001", "ScoreboardSilentDrop", "Detects silent returns in scoreboard write methods when expected queues are empty without logging an error. Spurious or unpredicted DUT packets are dropped, hiding hardware bugs."),
    ("UVM-SCB-002", "ScoreboardLeftoverQueue", "Scoreboard expected transaction queues must be checked for drain completeness in check_phase or report_phase. Missing drain checks allow dropped DUT packets to pass silently."),
    ("UVM-SEQ-001", "UvmSequenceDirectVifAccess", "Sequences and sequence items must not directly declare or drive virtual interface signals. Signal-level driving is the sole responsibility of the driver."),
    ("UVM-SEQ-002", "UvmSequencePrePostBodyMisuse", "pre_body() and post_body() callbacks in uvm_sequence are explicitly bypassed when the sequence is executed as a child sequence via `uvm_do or `uvm_do_with. Use pre_start() / post_start() or body() instead."),
    ("UVM-SEQ-003", "UvmPSequencerAbuse", "Using `uvm_declare_p_sequencer or accessing p_sequencer violates the Law of Demeter by tightly coupling the sequence data tier to physical sequencer component internals. Pass configuration down through sequence fields or uvm_config_db."),
    ("UVM-SEQ-004", "SequenceAbortSafety", "Detects calls to start_item() in UVM sequences that can bypass finish_item() via early return or break statements. An aborted sequence without finish_item() permanently deadlocks the sequencer's grant-wait queue."),
    ("UVM-SEQ-005", "EmptySequenceBody", "Detects sequence classes whose body() task contains no executable statements. Empty sequence bodies generate zero stimulus transactions."),
    ("UVM-SEQ-006", "UncheckedGetResponse", "Flags calls to get_response() in UVM sequences. Calling get_response() requires the driver to actively provide response items; otherwise, the sequencer response FIFO remains empty and deadlocks simulation."),
    ("UVM-SEQ-007", "SequencePriorityRange", "Flags sequence start() calls passing invalid negative priority values (< -1) which corrupt sequencer arbitration."),
    ("UVM-SEQ-008", "SequenceItemDefaultNew", "Requires sequence item constructor new() to provide a default value for the string name argument to support UVM factory creation and cloning."),
    ("UVM-SEQ-009", "SequenceBodyWithoutStartItem", "Flags calls to finish_item() inside uvm_sequence::body() that are not preceded by a corresponding start_item(). The UVM sequencer arbitration handshake strictly requires start_item() before finish_item()."),
    ("UVM-SEQ-010", "SequenceItemCreateWithoutType", "Flags sequence items created via direct new() inside sequence body(). Sequence items must be created via factory type_id::create() to allow testcase overrides."),
    ("UVM-SEQ-011", "UncheckedPSequencerCast", "Flags unchecked $cast(p_sequencer, m_sequencer) calls in sequences that do not verify the return status."),
    ("UVM-SEQ-012", "SequenceStartOnNullSequencer", "Flags sequence start(null) calls that start sequences without an attached sequencer handle."),
    ("UVM-SEQ-013", "SequenceItemTypeCompatibility", "Statically verifies that transaction item types between uvm_driver#(REQ) and uvm_sequencer#(REQ) are type-compatible across connect_phase connections."),
    ("UVM-SEQ-014", "UnusedSequence", "Flags a sequence that no other class in the compilation names, when the run also contains a test. Experimental: the sequence may be started from a file that was not linted."),
    ("UVM-SEQ-015", "UnusedSequenceItem", "Flags a sequence item that no other class in the compilation names, when the run also contains a test. Experimental: the item may be created from a file that was not linted."),
    ("UVM-SEQ-016", "SequencerFromConfigDb", "Flags uvm_config_db/uvm_resource_db get() calls in a sequence that fetch a sequencer handle. Bind sub-sequencers once, in a virtual sequencer or the test."),
    ("UVM-STR-005", "ComponentNullParentInCreate", "Flags UVM component factory create calls passing 'null' as the parent handle, creating orphaned hierarchy nodes."),
    ("UVM-STY-001", "UvmCreateStringMismatch", "String argument passed to type_id::create() must match the receiving variable name. Mismatched instance names break uvm_config_db hierarchy paths and targeted overrides."),
    ("UVM-STY-002", "ConstraintNameSuffix", "Enforces a naming standard requiring all constraint blocks to end with '_c' suffix."),
    ("UVM-STY-003", "ComponentNameMismatch", "Disallows passing hardcoded string literals to super.new() in uvm_component constructors. The constructor must forward the 'name' argument so the UVM factory can assign distinct instance names."),
    ("UVM-TLM-001", "UvmUnconnectedTlmPort", "Mandatory TLM ports and exports declared in uvm_component must be connected in connect_phase to prevent runtime fatal errors or null-pointer dereferences."),
    ("UVM-TLM-002", "UvmTlmTryGetUnchecked", "Flags calls to non-blocking TLM methods (try_get(), try_peek(), try_put()) where the boolean return status is ignored."),
    ("UVM-TLM-003", "UvmTlmPortSuffix", "Enforces standard UVM TLM port suffix naming conventions (_ap for analysis ports, _imp for imps, _export for exports, _port for ports, _fifo for TLM FIFOs)."),
    ("UVM-TLM-004", "TlmTopologyChecker", "Performs cross-component elaboration topology checks to verify that mandatory TLM ports (such as driver seq_item_pull_port and monitor analysis_port) are bound in connect_phase across the verification environment hierarchy."),
    ("UVM-TLM-005", "AnalysisTransactionMutation", "Detects in-place modification of transactions received via analysis write() methods. Because analysis ports broadcast by reference, modifying transaction fields directly causes silent data corruption across other concurrent subscribers and scoreboards."),
    ("UVM-TLM-006", "AnalysisFifoDrainStarvation", "Detects instantiated uvm_tlm_analysis_fifo components that receive transactions via connect_phase but have zero drain operations (.get(), .try_get()) across all task-based phases, causing unbounded simulation heap memory growth and fatal bad_alloc crashes."),
    ("UVM-TST-001", "CheckerCannotFail", "Flags scoreboard and checker classes with no way to report a failure: no `uvm_error or `uvm_fatal, no assertion and no comparator, in the class, its bases or the helpers it calls (Sonar S2699, tests without assertions)."),
    ("UVM-TST-002", "FixedDelayBeforeDrop", "Flags a constant #delay immediately before drop_objection(), used to let traffic drain (xUnit 'sleepy test', Sonar S2925)."),
    ("UVM-VIF-DIR", "VirtualInterfaceModportDriveInversion", "Detects procedural signal driving (via '=' or '<=') on virtual interface handles inside passive uvm_monitor components. Monitors must remain purely passive observers to avoid multi-driver electrical contention and X-propagation."),
    ("UVM-VSEQ-001", "VirtualSequencerWiringChecker", "Statically verifies that sub-sequencer handles declared within a virtual sequencer are fully wired and assigned in connect_phase across the verification environment."),
];

/// (id, name, category, severity, experimental, reported by, description) of
/// every rule and sub-rule, for `--explain`.
#[allow(clippy::type_complexity)]
pub(crate) const CATALOG: &[(&str, &str, &str, &str, bool, &str, &str)] = &[
    ("DPI-TYP-001", "DpiTypeWidthAlignment", "DPI", "WARNING", false, "", "Disallow 4-state types (integer, reg) in DPI-C declarations. 4-state types require complex svLogicVecVal structs in C; use 2-state portable types (int, longint, byte) for C99 ABI compatibility."),
    ("PORT-PRP-001", "ProprietaryVendorCalls", "Portability", "WARNING", false, "", "Disallow unguarded simulator-proprietary system tasks ($vcdpluson, $fsdbDumpvars, $shm_open). Vendor-specific calls prevent Verification IP from running on other simulators."),
    ("PORT-PTH-001", "HardcodedHostPaths", "Portability", "ERROR", false, "", "Disallow hardcoded absolute filesystem paths (/home/..., C:\\...) in file operations ($readmemh, $fopen). Absolute paths break regression execution in containerized CI/CD pipelines."),
    ("RAL-ACC-001", "DirectMirrorSetWithoutWrite", "UVM", "WARNING", false, "", "Flags direct reg.set(...) calls that update only software mirrors without issuing physical DUT write transactions."),
    ("RAL-ACC-002", "MissingBackdoorAccessPathDefinition", "UVM", "WARNING", false, "", "Flags RAL backdoor path configuration routines called with an empty string or null path."),
    ("RAL-ADP-001", "IncompleteRegAdapter", "UVM", "WARNING", false, "", "Flags uvm_reg_adapter subclasses whose bus2reg() never sets rw.status or whose reg2bus() never reads rw.kind. The register layer then reports every access as passed, or turns reads into writes (adapter pattern, MG-5.1)."),
    ("RAL-BLK-001", "RegBlockNeverLocked", "UVM", "ERROR", false, "", "Flags a top-level register block (held by an env or test, not by another block) on which lock_model() is never called. Until the model is locked, address maps are not built, so frontdoor accesses and get_reg_by_offset() fail."),
    ("RAL-COL-001", "RalAddressCollision", "UVM", "ERROR", false, "", "Detects duplicate/overlapping address offsets mapped in uvm_reg_block address maps. Address collisions cause silent register overwriting and hardware aliasing bugs."),
    ("RAL-MAP-001", "RalOrphanRegister", "UVM", "ERROR", false, "", "Detects instantiated uvm_reg instances inside uvm_reg_block that are never mapped via default_map.add_reg(). Orphan registers cause frontdoor access failures and verify phantom memory."),
    ("RAL-MAP-002", "RalMapAddressIntervalOverlap", "UVM", "ERROR", false, "", "Detects 1D address interval overlaps and register aliasing collisions within the same uvm_reg_map in a uvm_reg_block, preventing silent register corruption in hardware."),
    ("RAL-WIRE-001", "RalPredictorAdapterWiring", "UVM", "WARNING", false, "", "Verifies that all instantiated uvm_reg_predictor components have their .map property assigned in connect_phase. Without a map binding, explicit register prediction fails silently and register mirror values will never be updated during simulation."),
    ("SEC-LOG-001", "PlaintextKeyInLogs", "Security", "WARNING", false, "", "Detects plaintext logging of sensitive cryptographic assets (keys, seeds, secrets) via $sformatf/$display. Logging secrets compromises hardware security and violates ISO/SAE 21434 regression standards."),
    ("SV-API-001", "RefArgumentNeverWritten", "Maintainability", "INFO", false, "", "Flags ref arguments that the routine only reads; declare them const ref so callers know they are not modified (clang-tidy readability-non-const-parameter). Virtual methods are skipped because overrides share the signature."),
    ("SV-ARR-001", "OffByOneQueueIndex", "Correctness", "ERROR", false, "", "Detects out-of-bounds off-by-one queue and dynamic array indexing (e.g. 'q[q.size()]'). SystemVerilog silently returns uninitialized 'x/0 instead of raising an exception."),
    ("SV-ASC-001", "AssociativeArrayMutatingRead", "Performance", "WARNING", false, "", "Detects direct read lookups on associative arrays in expressions without checking exists(). In SystemVerilog (IEEE 1800 § 7.8.1), reading a missing key silently allocates and inserts it with a default value."),
    ("SV-BAN-001", "LegacyRegWireInTestbench", "Deprecated", "INFO", false, "", "Discourages legacy 'reg' and 'wire' keywords in SystemVerilog testbenches in favor of 'logic'."),
    ("SV-BUG-001", "IdenticalBranches", "Correctness", "WARNING", false, "", "Flags if/else and case branches whose bodies are token-identical to an earlier branch of the same statement (clang-tidy bugprone-branch-clone, Sonar S1871)."),
    ("SV-BUG-002", "RepeatedElseIfCondition", "Correctness", "WARNING", false, "", "Flags a condition that repeats an earlier condition of the same if/else-if chain, which makes the later branch dead (Sonar S1862)."),
    ("SV-BUG-003", "SelfAssignment", "Correctness", "WARNING", false, "", "Flags 'x = x' assignments, typically a constructor or setter whose argument shadows the property it was meant to set (clang-tidy bugprone-self-assignment, Sonar S1656)."),
    ("SV-BUG-004", "MismatchedFieldInCopyCompare", "Correctness", "ERROR", false, "", "In do_copy/do_compare and similar field-wise methods, flags a field of this object paired with a differently named field of the other object when the matching field exists."),
    ("SV-BUG-005", "IntegerDivisionToReal", "Correctness", "WARNING", false, "", "Flags integer divisions whose result is used as a real value, which truncates before the conversion (Sonar S2184, SpotBugs ICAST_IDIV_CAST_TO_DOUBLE)."),
    ("SV-BUG-006", "RealEquality", "Correctness", "WARNING", false, "", "Flags == and != on real or shortreal operands, except against an exact zero (Sonar S1244, clang-tidy float equality)."),
    ("SV-BUG-007", "SuspiciousArgumentOrder", "Correctness", "WARNING", false, "", "Flags positional calls where an argument's name matches a different parameter of the callee, such as write(len, addr) for write(addr, len) (clang-tidy readability-suspicious-call-argument, Sonar S2234)."),
    ("SV-CB-001", "ClockingBlockOutputReadSkew", "Concurrency", "WARNING", false, "", "Disallows reading output signals of a clocking block. Clocking block outputs are drive-only; reading them samples post-skew driven values with simulation race conditions."),
    ("SV-CMP-001", "CompilerError", "Correctness", "ERROR", false, "", "Reports the SystemVerilog compiler's errors (syntax, elaboration and type errors) as findings, so they appear in every report and in the editor next to the lint findings."),
    ("SV-CMP-002", "CompilerWarning", "Correctness", "WARNING", false, "SV-CMP-001", "Reports the SystemVerilog compiler's warnings as findings (controlled with -W options)."),
    ("SV-CNC-002", "CircularThreadWaitDeadlock", "Concurrency", "ERROR", false, "", "Detects circular lock acquisition orders and wait-for dependency cycles across concurrent threads in fork..join blocks, which cause guaranteed or probabilistic simulation deadlocks."),
    ("SV-CNC-003", "PollingLoop", "Concurrency", "WARNING", false, "", "Flags loops that test a flag or signal and wait a constant #delay between tests, instead of wait(), @ or an event (busy-wait smell, Sonar S2925)."),
    ("SV-CNC-004", "SharedWriteFromForks", "Concurrency", "WARNING", false, "", "Flags class properties written in two or more branches of one fork, or in a join_none thread and in its parent, without a semaphore (SpotBugs IS2_INCONSISTENT_SYNC)."),
    ("SV-CNS-001", "DefineForConstant", "Maintainability", "WARNING", false, "", "Flags `define macros whose body is only a number or a string, used as constants. A package parameter or localparam has a type and a scope; a macro is global to the rest of the compilation and can be redefined silently (MG-6.1)."),
    ("SV-CNS-002", "MacroAsRoutine", "Advisory", "INFO", false, "", "Flags multi-statement code macros that use nothing only a macro can do: no token pasting, stringification, nested macros, `__FILE__, type arguments, declarations or return/break. A function or task would be type-checked and debuggable (MG-6.1). Advisory: off by default."),
    ("SV-CNS-003", "IfdefInReusableClass", "Maintainability", "WARNING", false, "", "Flags `ifdef, `ifndef and `elsif inside class bodies, apart from simulator and UVM version shims. Compile-time switches multiply the variants of a class and cannot be chosen per instance; configuration can (MG-6.1)."),
    ("SV-CNS-004", "StringAsEnum", "Maintainability", "WARNING", false, "", "Flags a string variable compared against three or more literals in one case statement or if/else-if chain. The values form an enumeration the compiler cannot check; a typo in any of them fails silently (Fowler 'primitive obsession', MG-6.2). String arguments are SV-CPL-001's."),
    ("SV-CNS-005", "ManualBitFieldSlicing", "Advisory", "INFO", false, "", "Flags a vector that is cut into three or more different fixed part-selects (hdr[7:0], hdr[15:8], hdr[31:16]). The field layout lives in scattered numbers; a packed struct names it once (MG-6.2). Advisory: off by default."),
    ("SV-CNS-006", "ImplicitEnumBaseType", "Advisory", "INFO", false, "", "Flags enums in packages, classes and interfaces declared without a base type. They silently become 32-bit int, which wastes bits in packed items and no longer matches the width of the bus field they model (MG-6.3). Advisory: off by default."),
    ("SV-CNS-007", "LegacyIntegerType", "Advisory", "INFO", false, "", "Flags the Verilog-1995 type 'integer' in class code. It is a 4-state 32-bit signed value; int (2-state) or an explicitly sized logic vector says what is meant (MG-6.3). Advisory: off by default."),
    ("SV-CNS-008", "FunctionOutputArguments", "Advisory", "INFO", false, "", "Flags void class functions that hand their results back through output arguments. A return value, or a struct for several values, keeps the call an expression and makes the data flow visible (command-query separation, MG-6.3). Overrides are left alone, since their signature is fixed. Advisory: off by default."),
    ("SV-CON-004", "ConstantWaitCondition", "Concurrency", "ERROR", false, "", "Flags 'wait()' statements with compile-time constant conditions (e.g., 'wait(0);', 'wait(1);'). 'wait(0);' deadlocks the simulation thread permanently, while 'wait(1);' executes instantaneously."),
    ("SV-CON-005", "SemaphoreZeroKey", "Concurrency", "ERROR", false, "", "Flags semaphore method calls (sem.get(0), sem.put(0), sem.try_get(0)) passing non-positive key counts (<= 0)."),
    ("SV-CON-006", "EventTriggerInAlwaysComb", "Concurrency", "ERROR", false, "", "Disallows event triggers ('->' or '->>') inside always_comb blocks (IEEE 1800 § 9.2.2.2)."),
    ("SV-CON-007", "UnboundedMailboxInstantiation", "Concurrency", "WARNING", false, "", "Disallows instantiating unbounded mailboxes without a capacity limit to prevent memory bloat and missed producer-consumer synchronization."),
    ("SV-CON-008", "MutexTryGetWithoutCheck", "Concurrency", "WARNING", false, "", "Flags non-blocking semaphore or mutex try_get() calls whose return status is ignored, which risks threads executing critical sections without holding the lock."),
    ("SV-CON-009", "WaitForkWithoutFork", "Concurrency", "WARNING", false, "", "Flags 'wait fork;' statements in tasks or routines that contain no 'fork' blocks. Calling wait fork without spawning child processes can cause unintended hangs or dead code."),
    ("SV-CON-010", "DisableForkWithoutScope", "Concurrency", "ERROR", false, "", "Disallows calling 'disable fork;' directly at task or routine scope without an enclosing isolating 'fork ... join' block."),
    ("SV-CON-011", "WaitModifiedInLoop", "Concurrency", "WARNING", false, "", "Flags wait(...) statements inside loops where condition variables are never modified or assigned inside the loop body."),
    ("SV-CON-012", "ForkLoopVariableCapture", "Concurrency", "ERROR", false, "", "Disallows referencing loop variables directly inside 'fork ... join_none' or 'join_any' blocks without an automatic local variable copy."),
    ("SV-CON-013", "BlockingEventTriggerInClockedBlock", "Concurrency", "WARNING", false, "", "Disallows blocking event triggers (-> ev) inside clocked blocks; non-blocking triggers (->> ev) should be used instead."),
    ("SV-CON-014", "DisableNamedBlockInClass", "Concurrency", "WARNING", false, "", "Flags 'disable <block>' and 'disable <task>' inside class methods. A named-block or task disable acts on every running copy, so stopping one agent's thread also stops the same thread in all other instances. 'disable fork' is not flagged."),
    ("SV-CON-015", "UnguardedBlockingWait", "Concurrency", "WARNING", true, "", "Flags wait(vif.sig) and @(vif.sig) in drivers and sequences that are not raced against a timeout in fork ... join_any. Clock, reset and clocking-block events are not flagged, nor are tasks whose name says timeout or watchdog. Experimental: a watchdog elsewhere in the testbench may already cover the wait."),
    ("SV-COR-001", "TautologicalCheckCompare", "Correctness", "ERROR", false, "", "Detects tautological comparison between identical expressions (e.g. 'act_pkt.data == act_pkt.data'). Self-comparisons in scoreboards and checks always evaluate to true, masking hardware bugs."),
    ("SV-COR-005", "NonShortCircuitLogical", "Correctness", "WARNING", false, "", "Disallows using bitwise AND ('&') or bitwise OR ('|') instead of logical short-circuiting operators ('&&', '||') inside conditional statements."),
    ("SV-COR-006", "CaseWithoutDefault", "Correctness", "WARNING", false, "", "Flags 'case', 'casex', and 'casez' statements that lack an explicit 'default:' fallback branch."),
    ("SV-COR-007", "AssignmentInExpression", "Correctness", "WARNING", false, "", "Disallows assignment expressions ('=' or compound assignments) inside conditional predicates or loop conditions."),
    ("SV-COR-008", "SelfComparison", "Correctness", "ERROR", false, "", "Disallows self-comparisons where an operand is compared to itself (e.g. a == a), which tautologically evaluates to constant true or false."),
    ("SV-COR-009", "CasexProhibited", "Correctness", "ERROR", false, "", "Disallows use of 'casex' statements. 'casex' treats unknown simulation 'x' values as wildcards, masking uninitialized logic bugs and timing errors."),
    ("SV-COR-011", "ModifyingLoopIndexInsideFor", "Correctness", "WARNING", false, "", "Flags modifications to the loop control variable inside a 'for' loop body. Mutating the loop index inside the body causes infinite loops, skipped iterations, and indexing errors."),
    ("SV-COR-020", "ProceduralAssignmentAsSubExpression", "Correctness", "WARNING", false, "", "Disallows embedded assignment expressions used as sub-expressions within conditionals or arithmetic operations."),
    ("SV-COV-001", "UnreferencedCovergroup", "Coverage", "WARNING", false, "", "Detects covergroups declared in classes or modules that are never instantiated with 'new()' or never sampled. Unreferenced covergroups contribute 0 coverage samples, creating silent verification blind spots."),
    ("SV-COV-002", "ZeroWeightCoverpoint", "Coverage", "WARNING", false, "", "Flags covergroups, coverpoints, or crosses configured with option.weight or type_option.weight set to 0. Zero-weight coverage constructs collect samples but contribute 0% to regression coverage closure."),
    ("SV-COV-003", "CrossSameCoverpoint", "Coverage", "ERROR", false, "", "Detects coverage cross constructs crossing a coverpoint with itself (cross cp_a, cp_a). Crossing a coverpoint with itself creates redundant diagonal bins that distort coverage calculation."),
    ("SV-COV-004", "IllegalBinOverlap", "Coverage", "ERROR", false, "", "Detects overlapping values between regular 'bins' and 'illegal_bins' or 'ignore_bins' within a coverpoint. Per IEEE 1800 § 19.5, regular bins must not overlap with illegal or ignore bins."),
    ("SV-COV-005", "UnboundedTransitionBins", "Coverage", "WARNING", false, "", "Transition sequences in coverpoint bins must not specify unbounded repetitions (e.g., [*1:$], [->1:$]). Unbounded transition sequences cause exponential memory growth in simulator coverage databases."),
    ("SV-COV-006", "CovergroupCrossBinExplosion", "Coverage", "ERROR", false, "", "Disallows crossing 3 or more coverpoints without 'ignore_bins' or 'binsof' exclusion filters. Unfiltered multi-way crosses cause combinatorial auto-bin explosion, leading to simulator memory exhaustion."),
    ("SV-COV-007", "EmptyCovergroup", "Coverage", "WARNING", false, "", "Flags covergroups declared with zero coverpoints and zero crosses. An empty covergroup collects no coverage data."),
    ("SV-COV-008", "CrossWithEmptyBins", "Coverage", "WARNING", false, "", "Detects degenerate covergroup cross constructs specifying fewer than 2 coverpoints or empty cross products."),
    ("SV-COV-009", "CoverpointDefaultBinHazard", "Coverage", "WARNING", false, "", "Flags non-ignoring 'default' bins in coverpoints that mask uncovered stimulus and give a false sense of coverage closure."),
    ("SV-COV-010", "CrossWithAllBinsIgnored", "Coverage", "WARNING", false, "", "Flags covergroup cross constructs where all defined bins are ignore_bins, producing vacuous 0-bin coverage metrics."),
    ("SV-COV-011", "AtLeastZeroOrNegative", "Coverage", "WARNING", false, "", "Flags option.at_least or type_option.at_least set to 0 or negative values in covergroups/coverpoints. IEEE 1800 § 19.5 requires at_least to be a positive integer >= 1."),
    ("SV-COV-012", "WideCoverpointWithoutBins", "Coverage", "WARNING", false, "", "Flags coverpoints that define no explicit bins and omit option.auto_bin_max. Default auto-binning creates 64 bins, producing misleading 100% coverage closure on wide vectors."),
    ("SV-COV-013", "IgnoreBinsOverlapsIllegalBins", "Coverage", "ERROR", false, "", "Flags coverage models where the same value or range is specified in both 'ignore_bins' and 'illegal_bins' within a coverpoint."),
    ("SV-COV-014", "CoverpointWeightZero", "Coverage", "WARNING", false, "", "Flags covergroups or coverpoints where 'option.weight' or 'type_option.weight' is set to 0, silently excluding it from coverage scores."),
    ("SV-COV-015", "MissingIffOnCovergroupClock", "Coverage", "WARNING", false, "", "Covergroups sampled by a clocking event should specify an 'iff' reset guard condition."),
    ("SV-COV-016", "OverlappingRangesInCoverpointBin", "Coverage", "WARNING", false, "", "Flags coverpoint bins containing overlapping numerical value ranges."),
    ("SV-COV-017", "UnreachableCoverBin", "Coverage", "WARNING", false, "", "Flags coverpoint bins whose values all lie outside the range of the coverpoint expression (for example bins {[16:31]} on a 4-bit value). Such a bin can never be hit."),
    ("SV-CPL-001", "StringModeParameter", "Maintainability", "WARNING", false, "", "Flags routines whose string argument is compared against two or more literals to choose what to do, as in do_op(\"read\"). Caller and callee must agree on spellings the compiler never checks (control coupling, connascence of meaning, MG-2.4). Use an enum argument or separate routines. Overrides are left alone."),
    ("SV-DBC-001", "InterfaceWithoutAssertions", "Advisory", "INFO", false, "", "Flags an interface with clocking blocks or modports, so a protocol interface, that holds no assertions (assert/assume/cover property, immediate asserts, property declarations or checkers) and is not the target of a bind. Every bench that reuses it then re-checks the protocol by hand, or not at all (design by contract; MG-8.2). Advisory: off by default."),
    ("SV-DED-001", "UnusedVariable", "DeadCode", "INFO", false, "", "Local variables declared in tasks or functions should be referenced. Unused variables clutter code, consume memory, and often indicate incomplete logic."),
    ("SV-DED-002", "UnreachableStatementsPostReturn", "DeadCode", "WARNING", false, "", "Detects unreachable statements appearing after an unconditional control-flow termination (return, break, continue). Dead code clutters verification environments and hides logic errors."),
    ("SV-DED-003", "AccidentalEmptyConditional", "DeadCode", "ERROR", false, "", "Detects accidental semicolons immediately following if() or while() headers. An empty conditional branch causes subsequent blocks to execute unconditionally, introducing severe logic bugs."),
    ("SV-DED-004", "ConsecutiveDeadStore", "DeadCode", "WARNING", false, "", "Detects consecutive assignments to the same variable where the initial value is immediately overwritten without being read. Dead stores waste CPU cycles and frequently reveal copy-paste logic bugs."),
    ("SV-DED-005", "UnreadClassProperty", "DeadCode", "INFO", false, "", "Flags class properties that are assigned or written to, but never read anywhere in the class. Unread properties indicate dead instrumentation or abandoned design state."),
    ("SV-DED-006", "UnwrittenClassProperty", "DeadCode", "WARNING", false, "", "Flags non-rand class properties that lack an initializer, are read in methods, but never written or assigned. Unwritten properties always evaluate to uninitialized defaults, risking dead branches and silent logic bugs."),
    ("SV-DED-007", "UnusedPureRoutineResult", "DeadCode", "WARNING", false, "", "Flags calls to pure functions or value-returning routines ($sformatf, $realtime, len, toupper, sum) used as standalone statements where the result is discarded."),
    ("SV-DED-008", "UnusedGenerateBlock", "DeadCode", "INFO", false, "", "Flags conditional statements or generate blocks with constant false conditions ('0') and no 'else' clause."),
    ("SV-DED-009", "EmptyAlwaysOrInitial", "DeadCode", "WARNING", false, "", "Disallows initial, always, always_comb, always_ff, always_latch, or final procedural blocks with empty bodies."),
    ("SV-DED-010", "EmptyForkJoin", "DeadCode", "WARNING", false, "", "Disallows empty fork...join, fork...join_any, or fork...join_none blocks that contain zero statements."),
    ("SV-DED-011", "EmptyTaskOrFunction", "DeadCode", "WARNING", false, "", "Flags concrete, non-virtual, non-extern tasks and functions with empty bodies (zero statements). Empty routines cause useless call overhead and indicate incomplete or dead logic."),
    ("SV-DED-012", "UnreferencedParameter", "DeadCode", "WARNING", false, "", "Flags parameter and localparam declarations that are never referenced within their scope or testbench. Unused parameters create clutter and indicate dead or abandoned configurations."),
    ("SV-DED-013", "UnusedRoutineArgument", "Maintainability", "INFO", false, "", "Flags task and function arguments that the body never uses (clang-tidy misc-unused-parameters, Pylint W0613). Virtual methods and overrides, phase methods, DPI routines and empty bodies are skipped."),
    ("SV-DED-014", "UnusedLocalMethod", "Maintainability", "WARNING", false, "", "Flags a local task or function that no method of its class calls. A local method is invisible outside the class, so with no caller it is dead."),
    ("SV-DED-015", "NeverSetClassParameter", "Advisory", "INFO", false, "", "Flags a parameter of a user parameterized class that no specialization in the linted design ever sets. The class claims a flexibility nobody uses or verifies (Fowler 'speculative generality'); make it a localparam or drop it. Whole-program: a specialization in a file that was not linted is not seen, and only specializations used as a class member or base class are counted. Advisory: off by default."),
    ("SV-DEP-001", "ProgramBlockDeprecation", "Deprecated", "ERROR", false, "", "Disallow the obsolete SystemVerilog 'program' block. Modern verification architectures mandate 'module' with clocking blocks to prevent premature simulation termination."),
    ("SV-DEP-002", "DefparamDeprecation", "Deprecated", "ERROR", false, "", "Disallow 'defparam' statements. Parameter overrides must be specified directly on instance headers."),
    ("SV-DEP-003", "LegacyAlwaysBlock", "Deprecated", "WARNING", false, "", "Disallow untyped 'always' blocks. Enforces IEEE 1800 intent-specific blocks: always_comb, always_ff, or always_latch."),
    ("SV-DEP-004", "RandomSystemFunction", "Deprecated", "WARNING", false, "", "Disallow legacy Verilog '$random'. Replaced by '$urandom' and '$urandom_range' in IEEE 1800."),
    ("SV-DEP-005", "ProceduralContinuousAssign", "Deprecated", "ERROR", false, "", "Disallow procedural 'assign' and 'deassign' statements. Procedural continuous assignments are non-synthesizable and induce simulation race conditions."),
    ("SV-DEP-006", "NonAnsiPortList", "Deprecated", "INFO", false, "", "Disallow obsolete non-ANSI port list declarations. Enforces modern ANSI-style inline port lists."),
    ("SV-DLY-002", "IntraAssignmentDelay", "Correctness", "ERROR", false, "", "Disallows intra-assignment timing controls (e.g., a = #5 b; or a <= #5 b;) on procedural assignments. Intra-assignment delays cause simulation race conditions and are non-synthesizable."),
    ("SV-DLY-003", "RepeatLoopWithoutTiming", "Concurrency", "WARNING", false, "", "Flags repeat loops inside testbench tasks that contain no time-consuming statements (#, @, wait). Zero-delay repeat loops in tasks spin instantaneously in a single delta cycle, often indicating missing clock synchronization."),
    ("SV-DLY-004", "ZeroTimeForeverLoop", "Concurrency", "ERROR", false, "", "Flags forever loops whose body has no timing control, no task call and no exit, so the loop spins in zero simulation time and hangs the simulator."),
    ("SV-DRV-001", "DrivingDuringReset", "RTL_TB_Bridge", "WARNING", false, "", "Disallow driving virtual interface control signals without an active reset check or synchronization guard. Asserting handshake signals during reset violates physical bus protocols and corrupts hardware state."),
    ("SV-DSN-001", "TypeSwitchByName", "Architecture", "WARNING", false, "", "Flags branching on get_type_name() compared with string literals instead of virtual dispatch (Sonar 'instanceof chains', open/closed principle)."),
    ("SV-DSN-002", "GodClass", "Maintainability", "WARNING", false, "", "Flags classes that are very complex (WMC >= 47), use many other classes' data (ATFD > 5) and have low cohesion (TCC < 1/3): PMD's GodClass detection strategy."),
    ("SV-DSN-003", "LowCohesion", "Maintainability", "INFO", false, "", "Flags classes whose methods split into two or more groups that share no fields and do not call each other (LCOM4 > 1): the class is really several classes."),
    ("SV-DSN-004", "HighCoupling", "Maintainability", "INFO", false, "", "Flags classes other than envs and tests that reference more than 10 distinct user class types (CK coupling between objects, PMD CouplingBetweenObjects)."),
    ("SV-DSN-005", "DeepInheritance", "Maintainability", "INFO", false, "", "Flags classes with more than 3 user-defined ancestors above the UVM base class (CK depth of inheritance tree, Pylint too-many-ancestors)."),
    ("SV-DSN-006", "OverrideOnlyCallsSuper", "Maintainability", "INFO", false, "", "Flags overrides whose whole body is the super call with the same arguments, such as a connect_phase that only calls super.connect_phase(phase) (Pylint useless-parent-delegation, Sonar S1185). Constructors are kept."),
    ("SV-DSN-007", "EmptyOverrideOfConcrete", "Maintainability", "WARNING", false, "", "Flags an empty override of a user base-class method that has a body, which silently switches the inherited behavior off (Fowler 'refused bequest', Liskov substitution)."),
    ("SV-DSN-008", "MutablePackageState", "Architecture", "WARNING", false, "", "Flags non-const variables declared in packages. They are shared by every env instance and test in a run (clang-tidy cppcoreguidelines-avoid-non-const-global-variables)."),
    ("SV-DSN-009", "RepeatedEnumSwitch", "Advisory", "INFO", false, "", "Flags an enum that is switched on with case in three or more classes, a sign that behavior per kind belongs in a polymorphic item or policy class (Fowler 'repeated switches'). Advisory: off by default."),
    ("SV-DSN-010", "QueryChangesState", "Advisory", "INFO", false, "", "Flags functions named get_*, is_* or has_* that write class properties (command-query separation). get_next_* is allowed. Advisory: off by default."),
    ("SV-DSN-011", "FeatureEnvy", "Advisory", "INFO", false, "", "Flags a method that uses one other object's fields at least 6 times (option min_foreign) and more than twice as often as its own class's fields. The logic belongs with the data it uses (Fowler: Feature Envy; MG-3.1). Transactions, config objects, the same class and classes in the same hierarchy do not count, nor do copy/compare/print and build/connect methods. Advisory: off by default."),
    ("SV-DSN-012", "PrimitiveObsession", "Advisory", "INFO", false, "", "Flags a rand integral field of a sequence item or config that a constraint limits to a list of 3 to 16 single constant values ('x inside {0, 1, 2}'). The field is an enumeration: as an enum it prints by name in logs and waveforms and the compiler checks every value. Advisory: off by default."),
    ("SV-DSN-013", "FatalStubOverride", "Maintainability", "WARNING", false, "", "Flags an override of a user base-class method whose whole body is an error or fatal report (\"not supported here\"). The subclass refuses part of its parent's contract, so code holding a base handle fails at run time (Fowler 'refused bequest'). Split the base class instead. SV-DSN-007 covers empty overrides."),
    ("SV-DUP-001", "DuplicateMethodBody", "Maintainability", "WARNING", false, "", "Detects identical or copy-pasted subroutine method bodies across different classes. Duplicated code should be refactored into shared base classes or utilities."),
    ("SV-DUP-002", "CloneFragments", "Maintainability", "WARNING", false, "", "Finds runs of three or more statements (at least 50 tokens) that appear in more than one place, also when variables and literals were renamed consistently. Macro calls count as written, not as their expansion, and called names must match; runs that repeat one short cycle of statements, like unrolled loops, are left out. Each pair of routines is reported once; whole identical method bodies are SV-DUP-001's, and files whose header says they are generated are left out (DRY, Type-1/2 clones, MG-7.1)."),
    ("SV-DUP-003", "DuplicatedConstraint", "Maintainability", "WARNING", false, "", "Flags a constraint body repeated in two classes that do not inherit from each other. The rule then lives in two places and drifts; declare it once in a shared base class or a policy object (Fowler 'pull up', MG-7.1). SV-RND-011 covers repeats inside one class."),
    ("SV-DUP-004", "RepeatedStringLiteral", "Advisory", "INFO", false, "", "Flags a string literal, such as a report ID or a file name, written four or more times in the code. Config keys (UVM-CFG-008), instance names and class names are left out. One named constant keeps the copies in step (DRY, MG-7.1). Advisory: off by default."),
    ("SV-DUP-005", "CopiedAgentPackage", "Advisory", "INFO", false, "", "Flags two packages whose classes have the same roles, fields and method bodies apart from renamed identifiers, for at least three classes and 80% of the classes in the larger package (classes with almost no code are not counted). They are one agent copied and renamed; a parameterized agent, or a shared base with small subclasses, keeps one copy to fix (DRY, MG-7.2). Advisory: off by default."),
    ("SV-DUP-006", "DataClumps", "Advisory", "INFO", false, "", "Flags the same group of min_args (default 4) or more arguments (same names and types) declared by min_routines (default 3) or more routines. Values that always travel together belong in a transaction or struct; passing them one by one lets two same-typed arguments be swapped silently (Fowler 'data clumps'). Overrides are counted once, at the base declaration; each group is reported once, at its first routine. Advisory: off by default."),
    ("SV-ENC-001", "MutableObjectGetterLeak", "OOP", "WARNING", false, "", "Disallows getter functions (get_*()) from returning direct references to mutable internal class object members. Returning mutable handles leaks encapsulation; return a clone or copy instead."),
    ("SV-ERR-001", "FailureNotReported", "Correctness", "ERROR", false, "", "Flags randomize(), $cast(), uvm_config_db::get(), try_* and compare() status checks whose failure branch is empty or only reports below error severity (Sonar S108/S1166)."),
    ("SV-ERR-002", "UseAfterFailedNullCheck", "Correctness", "ERROR", false, "", "Flags a handle that a null check, a failed uvm_config_db::get() or a failed $cast() showed to be null, dereferenced later on the same path because the failure branch did not stop (SpotBugs NP_NULL_ON_SOME_PATH)."),
    ("SV-ERR-003", "ProcessTerminationInClass", "Correctness", "WARNING", false, "", "Flags $finish, $stop and $exit called from class methods. The run then skips the extract, check and report phases and the UVM report summary (Sonar S1147)."),
    ("SV-EVO-001", "Hotspot", "Advisory", "INFO", false, "", "With --history: reports the files that are both complex (summed cyclomatic complexity of their routines) and often changed in git, the top five by complexity times commits. Such hotspots are where defects collect and where refactoring pays first (Tornhill, MG-9.2). Advisory: off by default."),
    ("SV-EVO-002", "ChangeCoupling", "Advisory", "INFO", false, "", "With --history: reports two files in different packages that change together in at least three commits and in at least half of the commits touching either. The packages have a hidden dependency that their imports do not show; move the shared knowledge to one place (temporal coupling, MG-9.2). Advisory: off by default."),
    ("SV-EVT-001", "ZeroDelayEventWaitLoop", "Concurrency", "ERROR", false, "", "Using wait(event.triggered) inside a loop without an intervening time-advancing delay (@ or #) causes a zero-delay infinite delta loop that hangs the simulator at 100% CPU."),
    ("SV-FOR-001", "ForkInsideFunction", "Concurrency", "WARNING", false, "", "Disallows spawning concurrent threads with 'fork ... join/join_any/join_none' inside functions. Functions must remain synchronous and instantaneous per IEEE 1800 § 13.4.4."),
    ("SV-FSM-001", "NonExhaustiveEnumCase", "Correctness", "WARNING", false, "", "Case statement switching over an enum type does not explicitly handle all declared enum variants while using a default: arm. Catch-all default arms silently swallow newly added specification states and mask FSM decoder bugs."),
    ("SV-INT-001", "BlockingAssignmentToInterface", "Concurrency", "ERROR", false, "", "Disallows blocking assignments ('=') when driving virtual interface or clocking block signals. Clocking blocks and synchronous interface signals must be driven with non-blocking drives ('<=') per IEEE 1800 § 14.16."),
    ("SV-IPC-001", "TryPutIgnoredReturn", "Concurrency", "WARNING", false, "", "Non-blocking IPC routines (try_put, try_get, try_peek) return a boolean status. Ignoring the return value silently drops transactions when queues are full or empty."),
    ("SV-LANG-001", "EqualityWithXz", "Correctness", "ERROR", false, "", "Detects equality ('==', '!=') checks against 4-state unknown literals ('x, 'z). Logical equality against unknowns evaluates to 'x (false in branch conditions), silently masking bugs. Use case equality ('===', '!==') instead."),
    ("SV-LANG-002", "BitSelectOutOfBounds", "Correctness", "ERROR", false, "", "Detects static out-of-bounds bit or element selects on vectors and arrays with fixed ranges. SystemVerilog silently returns 'x for out-of-bounds accesses without crashing, causing silent data corruption."),
    ("SV-LANG-003", "UnsizedLiteralInConcat", "Correctness", "WARNING", false, "", "Disallow unbased unsized integer literals inside concatenations ({1, 0, data}). Per IEEE 1800 § 11.4.12, unbased constants expand to 32 bits each, causing unintended vector widening."),
    ("SV-LANG-004", "PartSelectReversed", "Correctness", "ERROR", false, "", "Detects reversed or inverted part-select slicing on vectors (e.g. vec[0:7] on logic [7:0] vec). Part-select slicing bounds must match the declared vector endianness."),
    ("SV-LANG-005", "NonBlockingInFunction", "Correctness", "ERROR", false, "", "Prohibits non-blocking assignments ('<=') to variables inside functions: the update lands after the caller has moved on. Interface and clocking block drives are exempt (IEEE 1800 § 13.4.4 allows non-blocking assignments in functions)."),
    ("SV-LOC-001", "ArrayLocatorEmptyQueueDeref", "Performance", "ERROR", false, "", "Disallows immediate element dereferencing on array locator methods (e.g., q.find()[0]). Locator methods return an unpacked queue that may be empty, causing out-of-bounds runtime errors (IEEE 1800 § 7.12.1)."),
    ("SV-LSP-001", "LspConstraintContradiction", "OOP", "ERROR", false, "", "Disallows unconditionally disabling inherited constraints via '.constraint_mode(0)' in derived classes. Disabling inherited constraints breaks base class contracts and violates the Liskov Substitution Principle (LSP)."),
    ("SV-MAC-001", "HeaderMacroLeak", "Portability", "WARNING", false, "", "Macros defined inside header files (.svh) must be undef'd with `undef before the end of the file unless registered as public API macros. Leaking macros causes silent parameter overrides and compilation collisions."),
    ("SV-MAC-002", "UnparenthesizedMacroArgument", "Correctness", "WARNING", false, "", "Flags expression macros that use an argument next to an operator without parentheses, or whose body is not wrapped in parentheses. `define DOUBLE(x) x*2 turns DOUBLE(a+1) into a+1*2; write `define DOUBLE(x) ((x)*2)."),
    ("SV-MET-001", "CognitiveComplexity", "Maintainability", "WARNING", false, "", "Flags routines whose Sonar cognitive complexity (nesting-weighted branching, with fork/join counted as nesting) exceeds the threshold (default 25; Sonar S3776)."),
    ("SV-MET-002", "LongRoutine", "Maintainability", "WARNING", false, "", "Flags routines with more statements than the threshold (default 100; clang-tidy readability-function-size, Checkstyle MethodLength)."),
    ("SV-MET-003", "TooManyArguments", "Maintainability", "WARNING", false, "", "Flags tasks and functions with more formal arguments than the threshold (default 7; Pylint R0913, Sonar S107). Overrides are judged at the base declaration only."),
    ("SV-MET-004", "DeepNesting", "Maintainability", "WARNING", false, "", "Flags routines whose control structures nest deeper than the threshold (default 5; Checkstyle NestedIfDepth, clang-tidy readability-function-size NestingThreshold)."),
    ("SV-MET-005", "ComplexCondition", "Maintainability", "WARNING", false, "", "Flags conditions with more && / || operators than the threshold (default 5; Pylint R0916, Checkstyle BooleanExpressionComplexity)."),
    ("SV-MET-006", "LargeClass", "Maintainability", "INFO", false, "", "Flags classes with more than 30 properties or 30 methods; config objects and sequence items may have 80 properties, register models are exempt (PMD TooManyFields and TooManyMethods, Pylint R0902/R0904)."),
    ("SV-MET-007", "LongTask", "Maintainability", "WARNING", false, "", "Flags tasks longer than the line budget (default 40 source lines, option max_lines). A long task is hard to review and to cover; split it into named tasks with one job each."),
    ("SV-MET-008", "RandFieldBudget", "Maintainability", "WARNING", false, "", "Flags a sequence item that declares more than the rand-field budget (default 8, option max_rand), counting rand and randc properties of the class itself. A wide item is slow to solve and hard to constrain; split the fields across items."),
    ("SV-MET-009", "ConfigKnobBudget", "Advisory", "WARNING", false, "", "Flags a configuration object (a uvm_object named *cfg* or *config*) that declares more than max_knobs (default 12) data members of its own. Split it into per-agent or per-feature sub-configs that the parent config holds. Advisory: SV-MET-006 already allows config objects up to 80 fields, so this stricter budget is opt-in."),
    ("SV-MOD-001", "GlobalUnitPollution", "Portability", "ERROR", false, "", "Disallow variables, nets, typedefs, tasks, and functions declared directly in the $unit compilation unit scope. Declarations outside a package or module cause cross-file namespace pollution and compile-order dependencies in multi-unit compilation."),
    ("SV-NAM-001", "UvmComponentNamingConvention", "Naming", "WARNING", false, "", "Enforces standard naming conventions for UVM components: classes derived from uvm_driver must end with '_driver', uvm_monitor with '_monitor', uvm_agent with '_agent', uvm_env with '_env', and uvm_test with '_test'."),
    ("SV-NAM-002", "PackageNamingConvention", "Naming", "WARNING", false, "", "Enforces that package identifiers end with '_pkg' (e.g., 'axi_pkg') to standardize namespaces."),
    ("SV-NAM-003", "InterfaceNamingConvention", "Naming", "WARNING", false, "", "Enforces that interface identifiers end with '_if' (e.g., 'axi_if') to standardize interface definitions."),
    ("SV-NAM-005", "UvmClassTypeSuffix", "Style", "WARNING", false, "", "Enforces standard verification naming suffix conventions for classes extending UVM base components (e.g. _seq, _item, _driver, _monitor, _scoreboard, _env)."),
    ("SV-NAM-100", "ConfigurableNamingEngine", "Style", "WARNING", false, "", "Parameterizable naming convention engine validating regex, prefix, suffix, and casing conventions across packages, interfaces, UVM classes, covergroups, and constraints."),
    ("SV-NAM-101", "PackageNaming", "Style", "WARNING", false, "SV-NAM-100", "Packages should end with '_pkg' for clean namespace identification."),
    ("SV-NAM-102", "InterfaceNaming", "Style", "WARNING", false, "SV-NAM-100", "Interfaces should end with '_if' suffix."),
    ("SV-NAM-103", "VirtualInterfaceNaming", "Style", "WARNING", false, "SV-NAM-100", "Virtual interface handles and typedefs should end with '_vif'."),
    ("SV-NAM-104", "ClassNaming", "Style", "WARNING", false, "SV-NAM-100", "General classes should follow PascalCase naming conventions."),
    ("SV-NAM-105", "CovergroupNaming", "Style", "WARNING", false, "SV-NAM-100", "Covergroup declarations must end with '_cg' suffix."),
    ("SV-NAM-106", "CoverpointNaming", "Style", "WARNING", false, "SV-NAM-100", "Coverpoints should start with 'cp_' prefix."),
    ("SV-NAM-107", "CrossNaming", "Style", "WARNING", false, "SV-NAM-100", "Cross coverages should start with 'cross_' or 'cx_' prefix."),
    ("SV-NAM-108", "AssertionNaming", "Style", "WARNING", false, "SV-NAM-100", "Concurrent assertions should have labels ending with '_a' or '_assert'."),
    ("SV-NAM-109", "ParameterNaming", "Style", "WARNING", false, "SV-NAM-100", "Parameters and constants should follow ALL_CAPS conventions."),
    ("SV-NAM-110", "TypedefEnumNaming", "Style", "WARNING", false, "SV-NAM-100", "Enum typedefs should end with '_e' suffix."),
    ("SV-NAM-111", "TypedefNaming", "Style", "WARNING", false, "SV-NAM-100", "User-defined typedefs should end with '_t' suffix."),
    ("SV-NAM-112", "ConstraintNaming", "Style", "WARNING", false, "SV-NAM-100", "Class constraint blocks should end with '_c' suffix."),
    ("SV-OCP-001", "CastTypeInspectionLadder", "OOP", "WARNING", false, "", "Disallows cascading $cast ladders (3+ branches) inspecting object types. Type inspection ladders violate the Open-Closed Principle (OCP); use virtual polymorphic methods instead."),
    ("SV-OOP-001", "NonVirtualMethodOverride", "OOP", "WARNING", false, "", "Overriding a non-virtual method in a derived class breaks polymorphism when accessed via a base class handle."),
    ("SV-OOP-002", "UncheckedDynamicCast", "OOP", "WARNING", false, "", "The return value of $cast(dest, src) must be checked (e.g., in an if statement or assert) to prevent silent null-pointer dereferences on cast failures."),
    ("SV-OOP-003", "MissingSuperNew", "OOP", "WARNING", false, "", "Constructors in derived classes should explicitly invoke super.new(...) to ensure base class state is initialized."),
    ("SV-OOP-004", "VariableShadowing", "OOP", "WARNING", false, "", "Detects variable shadowing where a derived class property shadows a base class property, or a method argument / local variable shadows a class member property."),
    ("SV-OOP-005", "VirtualCallInConstructor", "OOP", "WARNING", false, "", "Never call virtual methods inside constructors. In SystemVerilog, base constructors execute before child members are initialized, resulting in child methods operating on uninitialized data."),
    ("SV-OOP-006", "ClassShallowCopyAliasing", "OOP", "ERROR", false, "", "Using shallow copy (new other_obj) on classes containing nested object handles creates shared references across independent transactions. Use deep copy or clone() instead."),
    ("SV-OOP-007", "StaticMemberInUvmComponent", "Architecture", "ERROR", false, "", "Non-const static variable declared in a uvm_component subclass is shared across all instances simulation-wide. In multi-channel or multi-agent environments, instances will overwrite each other's state."),
    ("SV-OOP-008", "NonVirtualInterfaceInClass", "OOP", "ERROR", false, "", "Disallows declaring physical interface types inside classes without the 'virtual' keyword (IEEE 1800 § 25.9)."),
    ("SV-OOP-009", "EmptyVirtualMethodWithoutPure", "OOP", "INFO", false, "", "Flags virtual methods defined with empty bodies instead of being declared 'pure virtual' in abstract base classes."),
    ("SV-OOP-010", "ClassInstantiationInLoop", "Performance", "WARNING", false, "", "Disallows direct class instantiation via new() inside simulation loops to prevent heap contention and memory allocation overhead."),
    ("SV-OOP-011", "DowncastWithoutDynamicCast", "OOP", "ERROR", false, "", "Flags static casting syntax (e.g. DerivedClass'(base_handle)) applied to class objects. SystemVerilog requires dynamic casting via $cast() to verify runtime polymorphism."),
    ("SV-OOP-012", "ChainedAssignmentAliasing", "OOP", "WARNING", false, "", "Disallows chained assignment expressions (e.g. a = b = c;). Chained assignments create dangerous reference aliasing across class handles."),
    ("SV-OOP-013", "AbstractClassInstantiation", "OOP", "ERROR", false, "", "Disallows direct instantiation of abstract (virtual) classes via 'new()'. Only concrete derived classes can be instantiated."),
    ("SV-OOP-014", "SuperNewNotFirstStatement", "OOP", "WARNING", false, "", "Derived class constructors calling super.new(...) must invoke it as the very first procedural statement."),
    ("SV-OOP-015", "VirtualMethodSignatureMismatch", "OOP", "WARNING", false, "", "Virtual method overrides in derived classes must match the parameter count and signature of the base virtual method."),
    ("SV-PKG-001", "FileClassNameMismatch", "Architecture", "WARNING", false, "", "Flags `include'd class files that define more than one top-level class, or whose one class is not named after the file (my_drv.svh holding my_driver). With one class per file, named after it, a class can be found from its name and reused on its own (MG-1.2)."),
    ("SV-PKG-002", "WildcardImportOutsidePackage", "Architecture", "WARNING", false, "", "Flags 'import pkg::*' at file ($unit) scope, and inside files that are `include'd into a package. Both leak names into code that never asked for them and hide where a dependency comes from (information hiding, MG-1.3)."),
    ("SV-PKG-003", "UnusedPackageImport", "Architecture", "WARNING", false, "", "Flags package imports that supply no name used in their scope. An unused import is a false dependency: the package is compiled first, changes to it look relevant, and names it exports can collide with local ones (common reuse principle, MG-1.3)."),
    ("SV-PKG-004", "PackageLayerInversion", "Architecture", "WARNING", false, "", "Flags a package that imports a package from a higher testbench layer, such as an agent package importing an env or test package. The lower package can then not be compiled or reused without the higher one (acyclic and stable dependencies, MG-1.1). UVM-ARC-001 checks the same order between classes."),
    ("SV-PKG-005", "UnstablePackageDependedOn", "Advisory", "INFO", false, "", "Computes instability I = Ce / (Ca + Ce) for each user package from its imports and flags a package that depends on a less stable one. Many packages rely on a stable package, so its own dependencies should be at least as stable (Martin's stable dependencies principle, MG-1.4). Advisory: off by default."),
    ("SV-PRF-001", "PassArrayByValue", "Performance", "WARNING", false, "", "Passing dynamic arrays, queues, associative arrays, unpacked arrays, or unpacked structs by value (input) causes expensive memory duplication on every call. Use 'const ref' or 'ref' instead."),
    ("SV-PRF-002", "ArrayReductionWidthTruncation", "Performance", "ERROR", false, "", "Array reduction methods (.sum, .product) accumulate at element bit-width before extension to LHS. Summing sub-32-bit elements into 32/64-bit integers causes silent wraparound unless cast in with()."),
    ("SV-PRF-003", "DynArrayIncrementalResizeInLoop", "Performance", "WARNING", false, "", "Growing dynamic arrays incrementally inside loops with new[arr.size()+1](arr) causes O(N^2) memory reallocation bottlenecks. Pre-allocate with new[N] or use SystemVerilog queues instead."),
    ("SV-PRF-004", "ProceduralZeroDelay", "Performance", "WARNING", false, "", "Procedural delay #0 reschedules execution into the Inactive region. Repeated #0 rescheduling causes delta-cycle thrashing and degrades simulation throughput."),
    ("SV-PRF-005", "UnshieldedVerbosityFormatEval", "Performance", "WARNING", false, "", "Calling $sformatf inside uvm_info/warning without checking uvm_report_enabled formats strings even when messages are discarded by verbosity."),
    ("SV-PRF-006", "StringKeyAssociativeArray", "Performance", "WARNING", false, "", "Detects associative arrays indexed by 'string'. String keys incur hash calculation and dynamic string comparisons on every lookup and insert, degrading simulation throughput."),
    ("SV-PRF-007", "QueueConcatAppend", "Performance", "WARNING", false, "", "Disallow queue concatenation ('q = {q, x}' or 'q = {x, q}'). Concatenation reallocates memory on every append ($O(N^2)$ in loops); use push_back() or push_front() for amortized $O(1)$ performance."),
    ("SV-PRF-008", "QueueSlicePopFirst", "Performance", "WARNING", false, "", "Disallow queue slicing ('q = q[1:$]') to drop head elements. Queue slicing duplicates all remaining elements into new memory; use pop_front() for in-place $O(1)$ head-pointer advance."),
    ("SV-PRF-009", "NbaOnClassProperty", "Performance", "WARNING", false, "", "Disallow non-blocking assignments ('<=') on class properties. For heap-allocated class instances, NBAs force the simulator kernel to create dynamic event descriptors in the NBA region of the event wheel. Use blocking assignment ('=')."),
    ("SV-PRF-010", "StringConcatInLoop", "Performance", "WARNING", false, "", "Disallows iterative in-place string concatenation or $sformatf recursion inside loop bodies to prevent O(N^2) memory reallocation overhead."),
    ("SV-PRF-011", "DynamicArrayNewInLoop", "Performance", "WARNING", false, "", "Disallows dynamic array allocation (new[...]) inside simulation loops to prevent heap contention and memory churn."),
    ("SV-PRF-012", "UnboundedDynamicArrayInConstraint", "Performance", "WARNING", false, "", "Flags dynamic array or queue size constraints with an upper bound (< or <=) lacking an explicit lower bound."),
    ("SV-PRF-013", "ForkInClockedLoop", "Performance", "WARNING", false, "", "Flags fork/join, join_any, and join_none inside a clocked loop (always_ff, always @(posedge/negedge), or a loop that waits on a clock edge). A thread started on every clock piles work onto the scheduler."),
    ("SV-RCE-001", "ZeroDelayEventTrigger", "Concurrency", "WARNING", false, "", "Flags blocking event triggers ('-> event') which cause zero-delay simulation race conditions. Recommends non-blocking event triggers ('->> event') or persistent event evaluation ('wait(event.triggered)')."),
    ("SV-RDB-001", "PositionalFlagLiterals", "Maintainability", "INFO", false, "", "Flags calls that pass two or more 0/1 literals positionally to 1-bit arguments; use named argument binding (clang-tidy bugprone-argument-comment, Clean Code flag arguments)."),
    ("SV-RDB-002", "MagicNumber", "Advisory", "INFO", false, "", "Flags numeric literals other than 0, 1 and -1 in class method bodies: conditions, loop bounds and sizes; delays are left to the magic-delay rules (Checkstyle MagicNumber, Sonar S109). Advisory: off by default."),
    ("SV-RDB-003", "CommentedOutCode", "Advisory", "INFO", false, "", "Flags blocks of // comments that parse as SystemVerilog statements or declarations (Sonar S125). Advisory: off by default."),
    ("SV-RDB-004", "UndocumentedExtensionPoint", "Advisory", "INFO", false, "", "Flags new virtual methods without a preceding comment in classes meant to be extended: classes with user subclasses, classes named *base*, and callbacks (Checkstyle MissingJavadocMethod, Pylint C0116). Advisory: off by default."),
    ("SV-RDB-005", "RedundantBoolean", "Advisory", "INFO", false, "", "Flags 1-bit values compared with 1'b1/1'b0 and 'if (c) return 1; else return 0;' (Sonar S1125, clang-tidy readability-simplify-boolean-expr). Advisory: off by default."),
    ("SV-RDB-006", "DoubleNegativeFlag", "Advisory", "INFO", false, "", "Flags '!' (or '~' on one bit) applied to a variable whose name is negative (disable_*, no_*, not_*, skip_*, inhibit_*, ...). Advisory: off by default."),
    ("SV-RDB-007", "NonDescriptiveName", "Advisory", "INFO", false, "", "Flags class properties, and locals of routines longer than min_lines (default 10), named tmp, temp, val, obj, foo, d, t and the like (with or without a number; locals also data and value). Arguments and loop variables are not checked. Advisory: off by default."),
    ("SV-RDB-008", "UnclearAbbreviation", "Advisory", "INFO", false, "", "Flags class, property, method and local names containing a vowel-less word of four or more letters (trnsfr, chnnl, rgstr) that is not a common DV short form (clk, cfg, ctrl, jtag, ...). Each person drops different vowels, so such names defeat grep. Advisory: off by default."),
    ("SV-RDB-009", "RedundantComment", "Advisory", "INFO", false, "", "Flags a one-line // comment directly above a statement when every word of the comment (2 to 6 words, ignoring a, the, to, ...) is already a word of the statement's names, e.g. '// set cfg' above set_cfg(). Advisory: off by default."),
    ("SV-RDB-010", "UndocumentedTestbenchClass", "Advisory", "INFO", false, "", "Flags UVM components and sequences without a comment of at least min_words (default 10) words of prose right above the class. Copyright and license lines do not count. Advisory: off by default."),
    ("SV-RND-001", "UncheckedRandomize", "Randomization", "ERROR", false, "", "The return value of randomize() must be checked. Silently ignoring failure leaves transactions un-randomized or corrupt, concealing verification testbench bugs."),
    ("SV-RND-002", "GlobalRngInClass", "Randomization", "WARNING", false, "", "Calling $urandom or $random inside class components or sequences corrupts global thread random stability. Use std::randomize() or object-scoped randomization to preserve simulation repeatability."),
    ("SV-RND-003", "RandomizeMissingSuper", "Randomization", "WARNING", false, "", "Overridden pre_randomize() and post_randomize() callback methods must invoke super.pre_randomize() or super.post_randomize() to prevent bypassing base-class transaction setup and validation routines."),
    ("SV-RND-004", "InlineShadowNoLocal", "Randomization", "ERROR", false, "", "Detects inline constraint variable shadowing inside 'randomize() with' missing 'local::'. Unqualified identifiers resolve to target object properties, turning constraints into no-op tautologies."),
    ("SV-RND-005", "NonRandFieldConstrained", "Randomization", "ERROR", false, "", "Detects class member fields that are constrained in a constraint block but not declared 'rand' or 'randc'. The solver treats non-rand fields as fixed constants and will never randomize them."),
    ("SV-RND-006", "RandcMemoryExplosion", "Randomization", "ERROR", false, "", "Disallow wide vector declarations with 'randc' (> 16 bits). Cyclic permutation tracking across large state spaces causes simulator heap exhaustion and solver startup deadlocks."),
    ("SV-RND-008", "NonInvertibleConstraintOp", "Randomization", "WARNING", false, "", "Disallow non-invertible operators (%, /, **) inside constraint blocks. Non-linear operators prevent SAT/SMT solvers from bi-directionally pruning solution spaces, causing catastrophic backtracking and long simulation stalls."),
    ("SV-RND-009", "StaticConstraint", "Randomization", "WARNING", false, "", "Disallows static constraints. Static constraints share solver state across all class instances in the simulation, causing hidden dependencies and test flakiness."),
    ("SV-RND-010", "CyclicSolveBefore", "Randomization", "ERROR", false, "", "Detects cyclic dependencies in solve...before constraint ordering (e.g. solve a before b and solve b before a). Cyclic solve-before constraints create an unsatisfiable dependency graph in the solver."),
    ("SV-RND-011", "RedundantConstraint", "Randomization", "WARNING", false, "", "Detects duplicate or redundant constraint expressions within the same class scope. Redundant constraints enlarge solver expression graphs and increase solver solve latency without adding constraints."),
    ("SV-RND-012", "ZeroWeightDistribution", "Randomization", "ERROR", false, "", "Detects constraint distribution blocks where all weights evaluate to zero. At least one weight in a distribution must evaluate to non-zero per IEEE 1800 § 18.5.4."),
    ("SV-RND-013", "UnrestoredRandMode", "Randomization", "WARNING", false, "", "Flags '.rand_mode(0)' or '.constraint_mode(0)' calls that are never restored with '1' in the routine. Unrestored disabled random modes permanently corrupt stimulus generation for subsequent transactions."),
    ("SV-RND-014", "EmptyRandomizeWith", "Randomization", "WARNING", false, "", "Flags 'randomize() with {}' containing an empty inline constraint block. Empty inline constraint blocks incur dynamic solver scope allocation overhead while adding no constraints."),
    ("SV-RND-015", "UnconstrainedRandVariable", "Randomization", "WARNING", false, "", "Flags non-static 'rand' class properties that are never constrained in any constraint block within the class."),
    ("SV-RND-016", "ConcurrentRandomizeInFork", "Randomization", "WARNING", false, "", "Disallows concurrent calls to .randomize() on the same object handle across parallel fork threads without synchronization."),
    ("SV-RND-017", "RandcStateExhaustion", "Randomization", "WARNING", false, "", "Flags 'randc' cyclic variables declared with bit-width <= 2 bits (1 or 2 bits). State permutation tables for <= 4 states reset almost immediately, incurring solver overhead with no benefit."),
    ("SV-RND-018", "RandomizeInConstructor", "Randomization", "WARNING", false, "", "Disallows calling randomize() inside class constructors (new()). Randomizing during construction breaks derived-class constraint inheritance and factory overrides."),
    ("SV-RND-019", "ConstraintImplicationMultiBit", "Randomization", "WARNING", false, "", "Flags constraint implication expressions 'A -> B' where condition 'A' is a multi-bit vector without an explicit boolean comparison."),
    ("SV-RND-020", "RandcInDynamicContainer", "Randomization", "ERROR", false, "", "Disallows declaring 'randc' cyclic variables on dynamic arrays, queues, or associative arrays (IEEE 1800 § 18.4.1)."),
    ("SV-RND-021", "ConstraintInsideInvertedRange", "Randomization", "ERROR", false, "", "Disallows inverted value ranges [low : high] where low > high in set membership expressions."),
    ("SV-RND-022", "ConstraintCallingNonPureFunction", "Randomization", "ERROR", false, "", "Functions called in constraints must be pure and must not have side effects or void return types."),
    ("SV-RND-023", "UnallocatedRandObjectArray", "Randomization", "ERROR", false, "", "Flags rand arrays of class handles whose elements are never created. randomize() sizes a dynamic array but does not construct objects, so every element stays null and its rand members are never randomized."),
    ("SV-RND-024", "RandomizeInsideAssert", "Randomization", "WARNING", false, "", "Flags randomize() used as the condition of an immediate assert or assume. Turning assertions off also skips the randomization, so the object silently keeps stale values."),
    ("SV-RND-025", "DistWideRangeColonEq", "Randomization", "WARNING", false, "", "Flags '[lo:hi] := w' in a dist when the range holds more than max_range_values (default 16) values and the dist also has items of another size. ':=' applies the weight to each value, which is rarely what the author meant; ':/' shares it."),
    ("SV-RND-026", "UnrelatedSolveBefore", "Randomization", "WARNING", false, "", "Flags 'solve a before b' when no constraint of the class (or its base classes) ties a to b, directly or through other variables. The ordering then has no effect except to suggest a dependency that does not exist."),
    ("SV-RND-027", "SoftConstraintShadowing", "Randomization", "WARNING", false, "", "Flags soft constraints whose winner is hard to predict: 'soft' inside an inline randomize() with { } block, and a soft constraint on a variable that a base class or another constraint block of the same class already constrains softly. Keep soft defaults in one place, in the base class, and override with hard constraints."),
    ("SV-RSC-001", "LockNotReleased", "Concurrency", "ERROR", false, "", "Flags semaphore get()/try_get() and sequencer lock()/grab() that some path leaves without the matching put()/unlock()/ungrab(), such as an early return (Sonar S2222)."),
    ("SV-RSC-002", "FileHandleNotClosed", "Correctness", "WARNING", false, "", "Flags $fopen calls in classes that never call $fclose, which loses buffered trace data and exhausts file handles in long regressions (Sonar S2095)."),
    ("SV-SHD-002", "ForeachLoopVariableShadowing", "OOP", "WARNING", false, "", "Flags loop index variables in 'foreach (arr[i])' loops that shadow an existing class property or routine local variable."),
    ("SV-SML-001", "ScratchpadClassProperty", "Maintainability", "WARNING", false, "", "Disallow declaring scratchpad variables or loop induction counters as class properties. Move declarations to method stack frames to ensure thread safety and re-entrancy."),
    ("SV-SML-002", "MagicDelayInSequence", "Maintainability", "WARNING", false, "", "Disallow hardcoded physical delays (#delay) inside uvm_sequence. Sequences must be clocking-block and frequency agnostic."),
    ("SV-SML-003", "GenericReportId", "Maintainability", "INFO", false, "", "Disallow generic single-word report IDs ('ERR', 'INFO', 'DEBUG') in UVM reporting macros. Use feature-scoped hierarchical identifiers to support precise log filtering."),
    ("SV-SML-004", "CyclomaticComplexityGodMethod", "Maintainability", "WARNING", false, "", "Detects subroutines with high McCabe Cyclomatic Complexity ($M > 15$). Complex control flow obscures edge cases and inhibits functional verification."),
    ("SV-STR-001", "StreamingConcatenationSizeMismatch", "Correctness", "WARNING", false, "", "Disallows streaming concatenation operators ({>> { ... }} / {<< { ... }}) without explicit slice size. Unbounded slice streaming leads to silent truncation and byte alignment bugs per IEEE 1800 § 11.4.14."),
    ("SV-STY-001", "ClassMemberPrefix", "Style", "INFO", false, "", "Enforces that member properties of uvm_component classes begin with 'm_' prefix to distinguish local member state from arguments and parameters."),
    ("SV-STY-002", "MacroTrailingSemicolon", "Style", "WARNING", false, "", "Flags unnecessary semicolons following `uvm_* macro invocations that create empty statements in declarative or procedural scopes."),
    ("SV-STY-003", "TodoCommentTracker", "Style", "INFO", false, "", "Tracks unresolved TODO, FIXME, ICEBOX, HACK, and XXX comment markers across the codebase. Ensures temporary developer placeholders are addressed before tape-out or milestone delivery."),
    ("SV-STY-004", "TypedefNameSuffix", "Style", "WARNING", false, "", "Enforces naming conventions for typedefs: enums must end with '_e', and structs/data types must end with '_t'."),
    ("SV-STY-005", "MandatoryMatchingEndLabel", "Style", "INFO", false, "", "Enforces explicit and matching end labels on functions, tasks, and classes (e.g., endfunction : name). Prevents scope delimiter ambiguity in large verification codebases."),
    ("SV-STY-006", "MismatchedEndLabel", "Style", "WARNING", false, "", "Flags mismatched end labels on functions, tasks, and classes (e.g., function void foo(); ... endfunction : bar). Prevents scope delimiter confusion and copy-paste errors."),
    ("SV-STY-007", "MethodBannerStyle", "Style", "INFO", false, "", "Standardizes method separator pre-banners. Enforces 70–80 character uniform dashed separator lines and flags ragged or arbitrary-width comment separators."),
    ("SV-STY-008", "SectionHeaderBanner", "Style", "INFO", false, "", "Standardizes major section divider banners to uniform 70–80 character widths. Prevents ragged ASCII banners across verification packages and testbench files."),
    ("SV-STY-009", "ExternMethodThreshold", "Architecture", "WARNING", false, "", "Enforces 'extern' declaration for class methods exceeding N lines of code (default: 5 lines). Keeps class declarations concise and readable as clean interface definitions."),
    ("SV-STY-010", "ExplicitLiteralWidth", "Style", "WARNING", false, "", "Disallow unsized integer and numeric literals without explicit bit-width declarations. Prevents silent 32-bit zero-extension and sign extension bugs."),
    ("SV-STY-011", "OneStatementPerLine", "Style", "WARNING", false, "", "Prohibit multiple procedural statements on the same line separated by semicolons. Enforces clean formatting and deterministic single-stepping in simulation debuggers."),
    ("SV-STY-012", "SpaceKeywordParen", "Style", "INFO", false, "", "Requires a single space between control keywords (if, for, foreach, while, case) and opening parenthesis. Enforces common SystemVerilog code formatting guidelines."),
    ("SV-STY-013", "IncludeGuard", "Style", "ERROR", false, "", "Every included header file (.svh) must be wrapped in standard macro include guards (`ifndef / `define / `endif) to prevent circular definitions and compiler redefinition errors."),
    ("SV-STY-015", "TrailingWhitespace", "Style", "INFO", false, "", "Disallows trailing whitespace (spaces and tabs) at the end of lines in source files."),
    ("SV-STY-016", "MaxLineLength", "Style", "INFO", false, "", "Flags source lines exceeding 120 characters (option: max_columns) to preserve readability across split-view editors and terminal reviews."),
    ("SV-STY-100", "ConfigurableStyleEngine", "Style", "WARNING", false, "", "Parameterizable code style engine enforcing tab prohibitions, trailing whitespace limits, maximum line lengths, matching block end labels, and file naming."),
    ("SV-STY-101", "NoTabs", "Style", "WARNING", false, "SV-STY-100", "Literal tab characters are not allowed (style.allow_tabs)."),
    ("SV-STY-102", "NoTrailingWhitespace", "Style", "WARNING", false, "SV-STY-100", "Lines must not end in whitespace (style.allow_trailing_whitespace)."),
    ("SV-STY-103", "MaxLineLength", "Style", "WARNING", false, "SV-STY-100", "Lines must not exceed style.max_line_length characters."),
    ("SV-STY-104", "MatchingEndLabel", "Style", "WARNING", false, "SV-STY-100", "Blocks, routines and classes carry an end label that matches their name (style.mandatory_matching_end_label)."),
    ("SV-STY-105", "FileMatchesClassName", "Style", "WARNING", false, "SV-STY-100", "A file's base name matches the top-level class it defines."),
    ("SV-STY-106", "FileHeader", "Style", "WARNING", false, "SV-STY-100", "Files start with a header matching style.file_header_pattern (style.require_file_header)."),
    ("SV-SVA-001", "ImmediateAssertInCombinatorialLogic", "SVA", "WARNING", false, "", "Simple immediate assertions in always_comb or combinatorial blocks evaluate transient delta glitches. Convert to deferred immediate assertions (assert #0 or assert final) to wait for settled circuit values."),
    ("SV-SVA-002", "DisableIffComplexExpression", "SVA", "WARNING", false, "", "Flags 'disable iff (...)' clauses containing complex boolean expressions or multi-variable logic instead of simple reset conditions."),
    ("SV-SVA-003", "MixedClockEdgesInProperty", "SVA", "WARNING", false, "", "Flags SVA properties or assertions that mix both 'posedge' and 'negedge' clocking events."),
    ("SV-SVA-004", "NonConsecutiveRepetitionZeroBound", "SVA", "ERROR", false, "", "Non-consecutive repetition operators ([= ...] and [-> ...]) must specify a minimum bound >= 1."),
    ("SV-SVA-005", "MultiClockConcurrentAssertionDomain", "SVA", "ERROR", false, "", "Disallows concurrent assertions mixing multiple asynchronous clock domains without formal CDC qualification."),
    ("SV-SVA-006", "ComplexInlineProperty", "Advisory", "INFO", false, "", "Flags assert/assume/cover property statements whose inline property uses more than max_temporal_ops (default 3) temporal operators (##, |->, |=>, [*], throughout, within, until, ...). Advisory: off by default."),
    ("SV-SYS-001", "UncheckedFopen", "Security", "WARNING", false, "", "Flags unchecked $fopen return descriptors and discarded $fopen calls. File operations must check whether the descriptor is valid before performing file I/O."),
    ("SV-THR-001", "ForkLoopVariableShared", "Concurrency", "ERROR", false, "", "Spawning background threads with fork..join_none inside loops without copying the loop variable to an automatic local variable causes all threads to see the final loop index."),
    ("SV-THR-002", "StaticRoutineVariableLifetime", "Concurrency", "ERROR", false, "", "Non-class tasks and functions default to static lifetime in SystemVerilog. Local variables in static routines share memory addresses across concurrent calls, leading to intermittent corruption."),
    ("SV-THR-003", "UnboundedThreadSpawn", "Concurrency", "WARNING", false, "", "Flags fork ... join_none inside forever or while loops with no wait fork, disable fork or semaphore get in the loop to bound outstanding threads (thread-leak checks)."),
    ("SV-TIM-001", "TimescalePrecisionMismatch", "Correctness", "ERROR", false, "", "Flags `timescale directives where the time precision is coarser than the time unit (IEEE 1800 § 3.14.2)."),
    ("SV-TIM-002", "MissingTimescaleInModule", "Correctness", "WARNING", false, "", "Flags files and modules containing procedural delays (#) that lack an explicit `timescale or timeunit declaration."),
    ("SV-TST-001", "ConstantReseed", "Advisory", "INFO", false, "", "Flags srandom() or set_randstate() with a constant in components, sequences and other non-test classes; every seed of the regression then runs the same stimulus. Advisory: off by default."),
    ("SV-TYP-001", "MixedSignComparison", "Types", "WARNING", false, "", "Comparing signed and unsigned integers causes implicit unsigned coercion of the signed operand. Negative values evaluate as huge positive numbers, causing comparisons to silently invert logic."),
    ("SV-TYP-008", "RedundantCastToSameType", "Types", "WARNING", false, "", "Flags dynamic '$cast' calls or static type casts where the source and destination already have identical static types."),
    ("SV-TYP-009", "ArrayLiteralSizeMismatch", "Types", "WARNING", false, "", "Flags positional array assignment patterns '{...} where the number of elements does not match the target fixed array dimension."),
    ("SV-TYP-010", "TaskWithNonVoidReturnType", "Types", "ERROR", false, "", "Disallows declaring tasks with explicit non-void return types."),
    ("SVA-ACT-001", "AssertWithoutElse", "SVA", "WARNING", false, "", "Immediate and concurrent assertions must include an 'else' action block (e.g. 'else `uvm_error(...)'). Assertions without action blocks produce unhelpful one-line messages and cannot integrate with UVM reporting."),
    ("SVA-ACT-002", "TimeInAssertionAction", "SVA", "ERROR", false, "", "Action blocks of immediate and concurrent assertions must not consume simulation time (# delays, @ event controls, or wait statements) per IEEE 1800 § 16."),
    ("SVA-ACT-003", "SideEffectInAssertionAction", "SVA", "WARNING", false, "", "Flags assignments, increments and other writes inside the pass or fail action of an immediate or concurrent assertion. Reporting calls are fine; state changes vanish when assertions are disabled."),
    ("SVA-CTX-001", "ConcurrentAssertInFunction", "SVA", "ERROR", false, "", "Disallow concurrent assertions ('assert/assume/cover property') inside functions. Functions execute in zero simulation time and lack clocking contexts required by SVA semantics."),
    ("SVA-CYC-001", "SvaUnboundedDelay", "SVA", "WARNING", false, "", "Disallow unbounded cycle delays (##[1:$]) in SVA sequences. Unbounded delays cause simulator memory thread leaks and formal verification state-space explosions."),
    ("SVA-LBL-001", "UnlabeledAssertion", "SVA", "WARNING", false, "", "Immediate and concurrent assertions must declare an explicit label prefix (e.g. 'check_lbl: assert ...'). Lacking labels makes regression failure triage, ticket routing, and assertion control commands difficult."),
    ("SVA-RST-001", "DisableIffReset", "SVA", "WARNING", false, "", "Concurrent assertions and property declarations must include a 'disable iff (!rst_n)' clause to gate checking during power-on reset and warm resets, avoiding false-failure storms."),
    ("SVA-VAC-001", "SvaVacuousAntecedent", "SVA", "ERROR", false, "", "Detects constant-false antecedents in assertion implications (0 |-> ...). False antecedents cause vacuous passes, giving a false 100% pass metric while never verifying DUT behavior."),
    ("UVM-ALS-001", "UvmTransactionAliasing", "UVM", "WARNING", false, "", "Disallows in-place mutation of transaction objects after broadcasting via an analysis port (.write()). Analysis ports pass shared references; subsequent in-place mutations corrupt downstream scoreboards and subscribers."),
    ("UVM-API-001", "AccelleraOnlyApi", "Portability", "INFO", false, "", "Flags calls to, and classes extending, parts of the Accellera UVM library that IEEE 1800.2 does not define (tagged @uvm-accellera in the library source), such as uvm_component::print_config or uvm_port_base::debug_connected_to. Code that relies on them is tied to one UVM implementation and release. The list comes from the UVM API pack of the version being compiled."),
    ("UVM-API-002", "DeprecatedUvmMacro", "Deprecated", "WARNING", false, "", "Flags uses of UVM macros that the UVM version being compiled defines only under UVM_ENABLE_DEPRECATED_API (in UVM 2020: `uvm_do_with, `uvm_do_on, `uvm_do_pri, `uvm_create_on, `uvm_send_pri and the rest of that family). Without the define the code does not compile. The list comes from the UVM API pack of the version being compiled."),
    ("UVM-ARC-001", "LayerDependency", "Architecture", "WARNING", false, "", "Flags classes that depend on a higher testbench layer (item < sequence < agent < env < test), such as a sequence that references a scoreboard or an agent that references the env (ArchUnit layer rules)."),
    ("UVM-ARC-002", "HierarchyReachThrough", "Architecture", "WARNING", false, "", "Flags expressions that reach through three or more component handles (env.agt.drv.vif), outside connect_phase wiring (PMD LawOfDemeter, Fowler 'message chains')."),
    ("UVM-ARC-003", "FileIncludedInMultiplePackages", "Architecture", "ERROR", false, "", "Flags a file whose class definitions are `include'd into more than one package. Each package gets its own, incompatible type with the same name (C++ one-definition rule)."),
    ("UVM-ARC-004", "StringHierarchyLookup", "Architecture", "WARNING", false, "", "Flags uvm_root/uvm_component find(), find_all() and lookup() calls outside tests and end_of_elaboration_phase. Looking components up by path string is a service locator that hides dependencies and breaks silently when the hierarchy changes."),
    ("UVM-BAN-001", "UvmBannedFieldMacros", "Deprecated", "WARNING", false, "", "Bans the `uvm_field_* macro suite. Mandates manual do_copy, do_compare, and do_print methods to eliminate severe simulation performance overhead and uncontrollable deep copy bugs."),
    ("UVM-BAN-002", "UvmBannedUvmDoMacros", "Deprecated", "WARNING", false, "", "Discourages black-box `uvm_do macros in sequence bodies. Mandates explicit start_item / finish_item transaction handshakes."),
    ("UVM-BAN-003", "DirectDoMethodCall", "UVM", "WARNING", false, "", "Flags direct calls to do_copy, do_compare, do_print, do_pack, do_unpack and do_record. These are hooks for the public copy/compare/print/pack/record methods; calling them directly bypasses the policy object. super.do_*() inside an override is allowed."),
    ("UVM-CFG-001", "UvmConfigDbTypeMismatch", "UVM", "ERROR", false, "", "The type parameter in uvm_config_db#(T)::get must match the type parameter used in the corresponding set call for the same field name."),
    ("UVM-CFG-002", "UvmConfigDbNullContext", "UVM", "WARNING", false, "", "Passing 'null' as context to uvm_config_db inside a uvm_component breaks hierarchical scoping and prevents targeted configuration overrides. Use 'this' instead."),
    ("UVM-CFG-003", "UvmConfigDbGlobalWildcard", "UVM", "WARNING", false, "", "Calling uvm_config_db::set(null, \"*\", ...) with a null context and a bare wildcard or empty scope triggers global regex matching across every component in the testbench, severely degrading simulation startup."),
    ("UVM-CFG-004", "ConfigDbGetUnchecked", "UVM", "WARNING", false, "", "Flags calls to 'uvm_config_db#(...)::get()' where the boolean return status is ignored without being checked in an 'if' condition or assertion."),
    ("UVM-CFG-005", "ConfigDbCrossComponentResolver", "UVM", "ERROR", false, "", "Performs cross-component semantic resolution on uvm_config_db calls across the testbench hierarchy DAG to detect configuration type mismatches between set() and get() calls."),
    ("UVM-CFG-006", "PlusargsOutsideTest", "UVM", "WARNING", false, "", "Flags $test$plusargs, $value$plusargs and uvm_cmdline_processor reads in classes other than tests and config objects. Reading the command line deep inside components is hidden global configuration."),
    ("UVM-CFG-007", "ConfigDbAsRuntimeChannel", "UVM", "WARNING", false, "", "Flags uvm_config_db get, set, exists and wait_modified calls in the run-time phases of components and inside loops of any task. config_db is build-time wiring; used at run time it becomes a slow global mailbox (common coupling, MG-2.3)."),
    ("UVM-CFG-008", "ScatteredConfigKeyLiteral", "UVM", "WARNING", false, "", "Flags a uvm_config_db field name typed as a string literal in two or more files. The setter and getter only meet if both spell it the same; a shared constant makes the compiler check that (connascence of name, MG-2.4). Reported once per name."),
    ("UVM-CFG-009", "SharedConfigMutatedAtRuntime", "UVM", "WARNING", false, "", "Flags writes to fields of a config object that the class got from uvm_config_db and did not create, made outside new() and the build phases. The object is shared by everyone who read it, so the write is hidden global state (common coupling, MG-2.3)."),
    ("UVM-CFG-010", "ConfigDbGetWithoutSet", "UVM", "WARNING", true, "", "Flags a uvm_config_db::get whose string field name has no set in this compilation, when the compilation contains both sets and gets. Experimental: a set in a file that was not linted, or a field name built at run time, is invisible here."),
    ("UVM-CFG-011", "ConfigDbSetNeverGot", "UVM", "WARNING", true, "", "Flags a uvm_config_db::set whose string field name has no get in this compilation, when the compilation contains both sets and gets. Experimental: a get in a file that was not linted, or a field name built at run time, is invisible here."),
    ("UVM-CPL-002", "HandleToEnvOrTest", "UVM", "WARNING", false, "", "Flags sequences, items, agents, config objects and helpers that store a handle to a user env or test class. They then depend on everything the env contains and cannot be used under another env (stamp coupling, dependency inversion, MG-2.1)."),
    ("UVM-CPL-003", "ForeignComponentStateWrite", "UVM", "WARNING", false, "", "Flags assignments to properties of another component through a handle, except a parent setting up its own subtree in new() and the build, connect and end_of_elaboration phases (content coupling, MG-2.1). UVM-ARC-002 covers long read chains."),
    ("UVM-CPL-004", "HierarchicalReferenceInClass", "UVM", "WARNING", false, "", "Flags class code that names a module hierarchy (tb_top.dut.sig, $root.tb.x). Classes must reach the DUT only through virtual interfaces so they stay reusable (information hiding, MG-2.2)."),
    ("UVM-DAG-001", "UvmDanglingConfigString", "UVM", "ERROR", false, "", "Static UVM component DAG path matching: detects glob strings in uvm_config_db::set() that match zero instantiated components in the verification hierarchy. Typographical errors in string paths cause configurations to be silently dropped."),
    ("UVM-DEP-001", "UvmDeprecatedConfigCalls", "Deprecated", "ERROR", false, "", "Disallow deprecated legacy set_config_* and get_config_* methods (IEEE 1800.2 Annex H). Use type-safe uvm_config_db#(T)::set/get."),
    ("UVM-DEP-002", "UvmDeprecatedReportServer", "Deprecated", "WARNING", false, "", "Disallow direct singleton calls to uvm_report_server::get_server() (IEEE 1800.2 Annex H). Obtain report servers through uvm_coreservice_t."),
    ("UVM-DEP-003", "UvmDeprecatedPrinterKnobs", "Deprecated", "WARNING", false, "", "Disallow direct access to 'printer.knobs' (IEEE 1800.2 § 5.5.2). Use accessor methods on uvm_printer."),
    ("UVM-DEP-004", "UvmDeprecatedTestDone", "Deprecated", "ERROR", false, "", "Disallow obsolete OVM 'uvm_test_done' objection handle (IEEE 1800.2 Annex H). Attach objections to the active phase parameter."),
    ("UVM-FAC-001", "UvmComponentDirectNew", "UVM", "ERROR", false, "", "UVM components must be created using the UVM factory (type_name::type_id::create) instead of direct new() calls to support testbench overrides."),
    ("UVM-FAC-002", "UvmFactoryMacroMismatch", "UVM", "ERROR", false, "", "Classes derived from uvm_component must use `uvm_component_utils, and classes derived from uvm_object (non-component) must use `uvm_object_utils."),
    ("UVM-FAC-003", "UvmFactoryMissingUtils", "UVM", "WARNING", false, "", "Concrete classes derived from uvm_object or uvm_component must declare factory registration macros (`uvm_component_utils / `uvm_object_utils)."),
    ("UVM-FAC-004", "ParameterizedClassFactoryRegistration", "UVM", "ERROR", false, "", "Parameterized UVM components and objects must use `uvm_component_param_utils or `uvm_object_param_utils instead of non-parameterized utils macros."),
    ("UVM-FAC-005", "GlobalFactoryOverridePollution", "UVM", "WARNING", false, "", "Flags global factory type overrides (set_type_override, set_type_override_by_type, factory.set_type_override_by_name, T::type_id::set_type_override) outside uvm_test classes. They change the type for every test and VIP in the simulation; reusable components and sequences should use instance overrides scoped to their sub-tree."),
    ("UVM-LOG-002", "ProhibitedDisplayInUvm", "UVM", "WARNING", false, "", "Disallow direct $display/$write/$strobe calls inside UVM classes (components, objects, sequences). SystemVerilog display tasks bypass UVM reporting infrastructure, log redirection, and verbosity filtering."),
    ("UVM-NAM-101", "UvmDriverNaming", "Style", "WARNING", false, "SV-NAM-100", "UVM driver components must end with '_driver' or '_drv'."),
    ("UVM-NAM-102", "UvmMonitorNaming", "Style", "WARNING", false, "SV-NAM-100", "UVM monitor components must end with '_monitor' or '_mon'."),
    ("UVM-NAM-103", "UvmSequencerNaming", "Style", "WARNING", false, "SV-NAM-100", "UVM sequencers must end with '_sequencer' or '_sqr'."),
    ("UVM-NAM-104", "UvmSequenceNaming", "Style", "WARNING", false, "SV-NAM-100", "UVM sequence classes must end with '_seq' or '_sequence'."),
    ("UVM-NAM-105", "UvmSequenceItemNaming", "Style", "WARNING", false, "SV-NAM-100", "UVM transaction/sequence items must end with '_item' or '_seq_item'."),
    ("UVM-NAM-106", "UvmAgentNaming", "Style", "WARNING", false, "SV-NAM-100", "UVM agents must end with '_agent' suffix."),
    ("UVM-NAM-107", "UvmEnvNaming", "Style", "WARNING", false, "SV-NAM-100", "UVM environments must end with '_env' suffix."),
    ("UVM-NAM-108", "UvmTestNaming", "Style", "WARNING", false, "SV-NAM-100", "UVM test classes must end with '_test' suffix."),
    ("UVM-NAM-109", "UvmScoreboardNaming", "Style", "WARNING", false, "SV-NAM-100", "UVM scoreboards must end with '_scoreboard' or '_scb'."),
    ("UVM-OBJ-001", "UvmUnpairedObjection", "UVM", "ERROR", false, "", "Every phase.raise_objection() call must have a corresponding phase.drop_objection() within the same execution context to prevent simulation hangs or fatal errors."),
    ("UVM-OBJ-002", "UvmObjectionInLoop", "UVM", "WARNING", false, "", "Avoid raising and dropping objections inside high-frequency transaction loops to prevent severe simulation performance degradation."),
    ("UVM-OBJ-003", "ObjectionControlFlowMismatch", "UVM", "ERROR", false, "", "Performs control-flow graph (CFG) analysis on UVM phase and task routines to verify that every execution path containing raise_objection() is strictly guaranteed to reach a matching drop_objection() without early returns or asymmetric conditional branching."),
    ("UVM-OBJ-004", "OrphanSubsequenceObjectionHang", "UVM", "ERROR", false, "", "Detects background processes launched via fork..join_none inside UVM sequences that raise objections without a deterministic drop path, leaving orphan objections that hang simulation phases."),
    ("UVM-OBJ-005", "ObjectionWithoutDescription", "UVM", "INFO", false, "", "Flags raise_objection()/drop_objection() on a phase or objection with no description or an empty one. A short description makes objection traces of a hung test readable."),
    ("UVM-OBS-001", "ObserverStateMutationInWrite", "Architecture", "ERROR", false, "", "Mutating the observed transaction object inside a subscriber's write() method corrupts state for other concurrent subscribers in the Observer pattern. Clone the transaction before mutating."),
    ("UVM-OBS-002", "BlockingInObserver", "UVM", "ERROR", false, "", "Analysis write() implementations (uvm_subscriber::write and the write<SFX> methods behind uvm_analysis_imp<SFX>) must be functions that finish in zero time. Flags a write declared as a task, and a write that forks a thread per transaction."),
    ("UVM-PAT-001", "CallbackNotRegistered", "UVM", "WARNING", false, "", "Flags `uvm_do_callbacks(T, CB, ...) in classes where no `uvm_register_cb(T, CB) registers that pair for T or a base of T. UVM then refuses to add callbacks of that type at run time, so the hook never fires (MG-5.1)."),
    ("UVM-PAT-002", "HandRolledSingleton", "UVM", "WARNING", false, "", "Flags a class that keeps a static variable of its own type, the usual hand-rolled singleton. Every env and test in the run shares that one object, and a test cannot replace it. Pass the object through uvm_config_db or the resource database (MG-5.3)."),
    ("UVM-PAT-003", "NoExtensionPoint", "Advisory", "INFO", false, "", "Flags a driver or monitor whose run_phase is long (25 statements or more; option min_statements) while the class and its user bases declare no virtual hook methods and use no callbacks. A test or derived agent cannot then change one step, such as error injection or timing, without copying the whole run_phase (MG-5.2). Advisory: off by default."),
    ("UVM-PHS-001", "UvmMissingSuperPhase", "UVM", "WARNING", false, "", "Overridden standard UVM phases (e.g., build_phase, connect_phase) in uvm_component must call super.<phase_name>(phase) to ensure proper base-class configuration."),
    ("UVM-PHS-002", "UvmTimeInFunctionPhase", "UVM", "ERROR", false, "", "Function-based UVM phases (e.g., build_phase, connect_phase) must not consume simulation time using delays (#), event controls (@), or wait statements."),
    ("UVM-PHS-003", "UvmPhaseSignatureMismatch", "UVM", "ERROR", false, "", "Standard UVM phase methods must declare correct signatures (function void vs task, and a single argument of type uvm_phase)."),
    ("UVM-PHS-004", "SequenceInFunctionPhase", "UVM", "ERROR", false, "", "Disallow starting sequences (.start()) inside zero-time function phases (build_phase, connect_phase, etc.). Sequences require time-consuming simulation events and must be executed in task phases."),
    ("UVM-PHS-005", "SuperBuildPhaseOrder", "UVM", "WARNING", false, "", "Enforces that super.build_phase(phase) is the very first procedural statement in build_phase. Top-down phasing requires base class build_phase to execute before derived class configuration logic."),
    ("UVM-PHS-006", "PhaseObjectionMismatch", "UVM", "ERROR", false, "", "Detects 'phase.raise_objection()' calls without a matching 'phase.drop_objection()' in the same task or method. Unpaired objections prevent UVM phases from terminating, causing simulation hangs."),
    ("UVM-PHS-007", "UvmPhaseJumpHazard", "UVM", "WARNING", false, "", "Disallows manual phase jumping ('phase.jump(...)') in UVM testbenches due to objection leaks and scoreboard desynchronization risks."),
    ("UVM-PHS-008", "TimeInNonTimePhase", "UVM", "ERROR", false, "", "Disallows time-consuming statements (#, @, wait, ##) inside non-time-consuming UVM phases (e.g. build_phase, connect_phase, check_phase)."),
    ("UVM-PHS-009", "ObjectionInNonRunPhase", "UVM", "ERROR", false, "", "Disallows calling raise_objection() or drop_objection() inside non-run function phases (e.g. build_phase, connect_phase). Objections are strictly reserved for runtime phases."),
    ("UVM-PHS-010", "BuildPhaseCrossComponentAccess", "UVM", "WARNING", false, "", "Detects direct access to sibling components or cross-component handles during build_phase. Because the execution order of build_phase among sibling components is undefined in UVM, referencing sibling state during build_phase results in non-deterministic initialization races."),
    ("UVM-PHS-011", "RunPhaseWithRuntimePhases", "UVM", "WARNING", false, "", "Flags a component that overrides run_phase and also one of the runtime sub-phases (reset, configure, main, shutdown and their pre_/post_ phases). run_phase runs in parallel with all of them, so the two schedules race and readers cannot tell the order."),
    ("UVM-RAL-001", "DirectRalMirrorTampering", "Architecture", "ERROR", false, "", "Direct assignment to internal RAL fields (m_value, m_mirrored, m_desired) bypasses register callbacks, access policy checks, and prediction pipelines. Use predict() or bus operations instead."),
    ("UVM-REP-005", "LowVerbosityDebugReport", "UVM", "WARNING", false, "", "Flags UVM debug or trace messages configured with low verbosity (UVM_LOW or UVM_NONE)."),
    ("UVM-REP-006", "BlanketErrorDemotion", "UVM", "ERROR", false, "", "Flags report catchers that demote or swallow errors without filtering on ID or message, and severity overrides/actions that disable UVM_ERROR or UVM_FATAL for every ID (Pylint W0718 broad-exception-caught)."),
    ("UVM-REP-007", "CheckFailureAsWarning", "UVM", "WARNING", false, "", "Flags a failed compare() or an expected-versus-actual mismatch reported only with `uvm_warning or `uvm_info. The test still passes; check failures must be errors so they are counted (MG-8.1)."),
    ("UVM-REP-008", "FatalInCheckerPath", "UVM", "WARNING", false, "", "Flags `uvm_fatal on a data mismatch in scoreboards and subscribers. The run stops at the first mismatch and hides how many others there are; use `uvm_error and let max_quit_count stop the run (MG-8.1)."),
    ("UVM-REP-009", "InfoAtNoneVerbosity", "UVM", "INFO", true, "", "Flags `uvm_info messages at UVM_NONE verbosity, which cannot be filtered with +UVM_VERBOSITY. Experimental: measuring how often real benches use UVM_NONE on purpose."),
    ("UVM-ROL-001", "DriverGeneratesStimulus", "UVM", "WARNING", false, "", "Flags drivers that randomize sequence items or start sequences. Stimulus belongs in sequences, where tests can layer constraints and the sequencer can arbitrate; a driver only converts items to pin activity (single responsibility, MG-3.1)."),
    ("UVM-ROL-002", "CoverageOutsideObservers", "UVM", "WARNING", false, "", "Flags covergroups declared in drivers and sequences. They sample what was intended, not what reached the DUT, and disappear when the agent is passive; collect coverage in a monitor or subscriber (MG-3.1)."),
    ("UVM-ROL-003", "DutCheckingInAgent", "UVM", "WARNING", false, "", "Flags agents that hold a scoreboard, predictor or reference model. Agents carry protocol knowledge only; DUT-specific checking belongs in the env so the agent can be reused with other DUTs (MG-3.2)."),
    ("UVM-ROL-004", "TestBuildsLeafComponents", "UVM", "WARNING", false, "", "Flags tests that create drivers, monitors, sequencers, agents, scoreboards or subscribers directly. Tests configure and select; the env builds, so every test shares one structure (facade, MG-3.3)."),
    ("UVM-ROL-005", "MonitorDependsOnActivePath", "UVM", "WARNING", false, "", "Flags monitors that hold a handle to a driver, sequencer or sequence item port. A monitor must work on its own, observing only the interface, or it breaks in passive agents (MG-3.1)."),
    ("UVM-ROL-006", "VirtualInterfaceInChecker", "UVM", "WARNING", false, "", "Flags virtual interface handles in scoreboards and subscribers. Pin timing belongs in drivers, monitors and interface assertions; a checker that waits on signals cannot run against a transaction-level model or an emulator, and hides a second monitor. Sequences are covered by UVM-SEQ-001."),
    ("UVM-ROL-007", "ProceduralTimeoutInMonitor", "Advisory", "INFO", false, "", "Flags fork ... join_any blocks in a monitor where one branch counts clock cycles (repeat (N) @(...)) and then reports an error: a handshake timeout written as procedural code. A concurrent assertion in the interface states the same rule in one line and checks it every cycle. Advisory: off by default."),
    ("UVM-RUS-001", "AgentIgnoresIsActive", "UVM", "WARNING", false, "", "Flags agents that create their driver or sequencer without checking is_active or get_is_active(). Such an agent cannot be reused as a passive monitor in a larger env (MG-4.1)."),
    ("UVM-RUS-002", "AgentWithoutConfigObject", "UVM", "WARNING", false, "", "Flags agents and envs that read three or more separate scalar settings from uvm_config_db instead of one config object (Fowler 'data clumps', MG-4.2)."),
    ("UVM-RUS-003", "HardcodedTopology", "UVM", "WARNING", false, "", "Flags envs that create components in a loop with a literal count instead of a count from their config object (open/closed principle, MG-4.2)."),
    ("UVM-RUS-004", "AbsoluteConfigDbPath", "UVM", "WARNING", false, "", "Flags uvm_config_db calls in classes whose path starts at uvm_test_top. Below the test the path should be relative to 'this'; with a non-null context an absolute path is appended to the context and never matches (MG-4.3)."),
    ("UVM-RUS-005", "OverrideByNameString", "UVM", "WARNING", false, "", "Flags factory overrides and creates that name types with string literals (set_type_override_by_name, set_inst_override, create_object ...). A typo or rename is only found at run time; T::type_id::set_type_override() is checked by the compiler (connascence of name, MG-4.3)."),
    ("UVM-RUS-006", "IncompleteItemContract", "UVM", "WARNING", false, "", "Flags concrete sequence items with fields that implement neither field macros nor do_copy(), do_compare() and convert2string()/do_print(). Scoreboards, clone() and debug prints then silently see default behaviour (MG-4.4)."),
    ("UVM-SCB-001", "ScoreboardSilentDrop", "UVM", "ERROR", false, "", "Detects silent returns in scoreboard write methods when expected queues are empty without logging an error. Spurious or unpredicted DUT packets are dropped, hiding hardware bugs."),
    ("UVM-SCB-002", "ScoreboardLeftoverQueue", "UVM", "ERROR", false, "", "Scoreboard expected transaction queues must be checked for drain completeness in check_phase or report_phase. Missing drain checks allow dropped DUT packets to pass silently."),
    ("UVM-SEQ-001", "UvmSequenceDirectVifAccess", "UVM", "WARNING", false, "", "Sequences and sequence items must not directly declare or drive virtual interface signals. Signal-level driving is the sole responsibility of the driver."),
    ("UVM-SEQ-002", "UvmSequencePrePostBodyMisuse", "Architecture", "WARNING", false, "", "pre_body() and post_body() callbacks in uvm_sequence are explicitly bypassed when the sequence is executed as a child sequence via `uvm_do or `uvm_do_with. Use pre_start() / post_start() or body() instead."),
    ("UVM-SEQ-003", "UvmPSequencerAbuse", "Architecture", "WARNING", false, "", "Using `uvm_declare_p_sequencer or accessing p_sequencer violates the Law of Demeter by tightly coupling the sequence data tier to physical sequencer component internals. Pass configuration down through sequence fields or uvm_config_db."),
    ("UVM-SEQ-004", "SequenceAbortSafety", "UVM", "ERROR", false, "", "Detects calls to start_item() in UVM sequences that can bypass finish_item() via early return or break statements. An aborted sequence without finish_item() permanently deadlocks the sequencer's grant-wait queue."),
    ("UVM-SEQ-005", "EmptySequenceBody", "UVM", "WARNING", false, "", "Detects sequence classes whose body() task contains no executable statements. Empty sequence bodies generate zero stimulus transactions."),
    ("UVM-SEQ-006", "UncheckedGetResponse", "UVM", "WARNING", false, "", "Flags calls to get_response() in UVM sequences. Calling get_response() requires the driver to actively provide response items; otherwise, the sequencer response FIFO remains empty and deadlocks simulation."),
    ("UVM-SEQ-007", "SequencePriorityRange", "UVM", "WARNING", false, "", "Flags sequence start() calls passing invalid negative priority values (< -1) which corrupt sequencer arbitration."),
    ("UVM-SEQ-008", "SequenceItemDefaultNew", "UVM", "WARNING", false, "", "Requires sequence item constructor new() to provide a default value for the string name argument to support UVM factory creation and cloning."),
    ("UVM-SEQ-009", "SequenceBodyWithoutStartItem", "UVM", "ERROR", false, "", "Flags calls to finish_item() inside uvm_sequence::body() that are not preceded by a corresponding start_item(). The UVM sequencer arbitration handshake strictly requires start_item() before finish_item()."),
    ("UVM-SEQ-010", "SequenceItemCreateWithoutType", "UVM", "WARNING", false, "", "Flags sequence items created via direct new() inside sequence body(). Sequence items must be created via factory type_id::create() to allow testcase overrides."),
    ("UVM-SEQ-011", "UncheckedPSequencerCast", "UVM", "WARNING", false, "", "Flags unchecked $cast(p_sequencer, m_sequencer) calls in sequences that do not verify the return status."),
    ("UVM-SEQ-012", "SequenceStartOnNullSequencer", "UVM", "WARNING", false, "", "Flags sequence start(null) calls that start sequences without an attached sequencer handle."),
    ("UVM-SEQ-013", "SequenceItemTypeCompatibility", "UVM", "WARNING", false, "", "Statically verifies that transaction item types between uvm_driver#(REQ) and uvm_sequencer#(REQ) are type-compatible across connect_phase connections."),
    ("UVM-SEQ-014", "UnusedSequence", "UVM", "WARNING", true, "", "Flags a sequence that no other class in the compilation names, when the run also contains a test. Experimental: the sequence may be started from a file that was not linted."),
    ("UVM-SEQ-015", "UnusedSequenceItem", "UVM", "WARNING", true, "", "Flags a sequence item that no other class in the compilation names, when the run also contains a test. Experimental: the item may be created from a file that was not linted."),
    ("UVM-SEQ-016", "SequencerFromConfigDb", "UVM", "WARNING", false, "", "Flags uvm_config_db/uvm_resource_db get() calls in a sequence that fetch a sequencer handle. Bind sub-sequencers once, in a virtual sequencer or the test."),
    ("UVM-STR-005", "ComponentNullParentInCreate", "UVM", "WARNING", false, "", "Flags UVM component factory create calls passing 'null' as the parent handle, creating orphaned hierarchy nodes."),
    ("UVM-STY-001", "UvmCreateStringMismatch", "Style", "WARNING", false, "", "String argument passed to type_id::create() must match the receiving variable name. Mismatched instance names break uvm_config_db hierarchy paths and targeted overrides."),
    ("UVM-STY-002", "ConstraintNameSuffix", "Style", "WARNING", false, "", "Enforces a naming standard requiring all constraint blocks to end with '_c' suffix."),
    ("UVM-STY-003", "ComponentNameMismatch", "UVM", "ERROR", false, "", "Disallows passing hardcoded string literals to super.new() in uvm_component constructors. The constructor must forward the 'name' argument so the UVM factory can assign distinct instance names."),
    ("UVM-TLM-001", "UvmUnconnectedTlmPort", "UVM", "WARNING", false, "", "Mandatory TLM ports and exports declared in uvm_component must be connected in connect_phase to prevent runtime fatal errors or null-pointer dereferences."),
    ("UVM-TLM-002", "UvmTlmTryGetUnchecked", "UVM", "WARNING", false, "", "Flags calls to non-blocking TLM methods (try_get(), try_peek(), try_put()) where the boolean return status is ignored."),
    ("UVM-TLM-003", "UvmTlmPortSuffix", "Style", "WARNING", false, "", "Enforces standard UVM TLM port suffix naming conventions (_ap for analysis ports, _imp for imps, _export for exports, _port for ports, _fifo for TLM FIFOs)."),
    ("UVM-TLM-004", "TlmTopologyChecker", "UVM", "WARNING", false, "", "Performs cross-component elaboration topology checks to verify that mandatory TLM ports (such as driver seq_item_pull_port and monitor analysis_port) are bound in connect_phase across the verification environment hierarchy."),
    ("UVM-TLM-005", "AnalysisTransactionMutation", "UVM", "WARNING", false, "", "Detects in-place modification of transactions received via analysis write() methods. Because analysis ports broadcast by reference, modifying transaction fields directly causes silent data corruption across other concurrent subscribers and scoreboards."),
    ("UVM-TLM-006", "AnalysisFifoDrainStarvation", "UVM", "WARNING", false, "", "Detects instantiated uvm_tlm_analysis_fifo components that receive transactions via connect_phase but have zero drain operations (.get(), .try_get()) across all task-based phases, causing unbounded simulation heap memory growth and fatal bad_alloc crashes."),
    ("UVM-TST-001", "CheckerCannotFail", "UVM", "ERROR", false, "", "Flags scoreboard and checker classes with no way to report a failure: no `uvm_error or `uvm_fatal, no assertion and no comparator, in the class, its bases or the helpers it calls (Sonar S2699, tests without assertions)."),
    ("UVM-TST-002", "FixedDelayBeforeDrop", "UVM", "WARNING", false, "", "Flags a constant #delay immediately before drop_objection(), used to let traffic drain (xUnit 'sleepy test', Sonar S2925)."),
    ("UVM-VIF-DIR", "VirtualInterfaceModportDriveInversion", "UVM", "ERROR", false, "", "Detects procedural signal driving (via '=' or '<=') on virtual interface handles inside passive uvm_monitor components. Monitors must remain purely passive observers to avoid multi-driver electrical contention and X-propagation."),
    ("UVM-VSEQ-001", "VirtualSequencerWiringChecker", "UVM", "WARNING", false, "", "Statically verifies that sub-sequencer handles declared within a virtual sequencer are fully wired and assigned in connect_phase across the verification environment."),
];

/// (id, level, statement) of each methodology guideline (docs/methodology).
pub(crate) const GUIDELINES: &[(&str, &str, &str)] = &[
    ("MG-1.1", "Shall", "Dependencies point down the testbench stack: item, sequence, agent, env, test. Nothing lower knows about anything higher."),
    ("MG-1.2", "Should", "One class per file, and the file is named after the class."),
    ("MG-1.3", "Shall", "Each file belongs to one package; declarations, imports and macros stay inside it and do not leak into $unit or other files."),
    ("MG-1.4", "May", "Packages that many others depend on stay small and stable."),
    ("MG-2.1", "Shall", "Components talk through TLM ports, config objects and sequences; they do not hold handles to envs and tests or write each other's state."),
    ("MG-2.2", "Shall", "Class code never names a module hierarchy; virtual interfaces arrive through configuration."),
    ("MG-2.3", "Should", "Shared state is passed down at build time, not kept in globals, statics, the command line or run-time hierarchy lookups."),
    ("MG-2.4", "Should", "Names and positions that tie code together (config keys, value types, argument order) match on both sides and are checked, not left to convention."),
    ("MG-3.1", "Shall", "Each UVM role does one job: sequences generate, drivers drive, monitors observe, scoreboards check, subscribers cover."),
    ("MG-3.2", "Should", "Agents carry protocol knowledge only; DUT-specific checking lives in the env."),
    ("MG-3.3", "Should", "Tests configure and select; envs build."),
    ("MG-4.1", "Shall", "Every agent works in both active and passive mode."),
    ("MG-4.2", "Shall", "Agent and env behaviour is controlled by a config object, not by literals or scattered config_db fields."),
    ("MG-4.3", "Should", "Overrides and lookups use types, not strings; config scopes are relative; nothing names a host path or a vendor-only call."),
    ("MG-4.4", "Should", "Sequence items carry their full object contract: copy, compare and print."),
    ("MG-4.5", "Shall", "Every reusable class is registered with the factory and created through it."),
    ("MG-5.1", "Shall", "When a pattern's mechanism is used, all of its parts are present: callbacks are registered, adapters are complete, ports and sequencers are wired."),
    ("MG-5.2", "Should", "Behaviour varies through overrides, hooks and callbacks, not type switches or edits to the base class; overrides keep the base contract."),
    ("MG-5.3", "Should", "No hand-rolled singletons; shared services go through the config or resource database."),
    ("MG-6.1", "Shall", "Prefer typed language constructs to the preprocessor and to code-generating macros."),
    ("MG-6.2", "Should", "Model domain values with types: enums instead of strings, packed structs instead of hand slicing."),
    ("MG-6.3", "Shall", "Use current, explicit language and UVM constructs; deprecated and legacy forms are not used."),
    ("MG-7.1", "Should", "Copy-paste is refactored into a shared base, helper or parameterized class by the third copy."),
    ("MG-7.2", "May", "Near-identical agents become one parameterized agent."),
    ("MG-8.1", "Shall", "Every check that can fail reports through UVM at error severity, so failures are counted and never hidden."),
    ("MG-8.2", "Should", "Reusable interfaces carry their own protocol assertions."),
    ("MG-9.1", "Should", "Routines and classes stay within complexity and size budgets, and dead or commented-out code is removed."),
    ("MG-9.2", "May", "Complex code that changes often is refactored first."),
];
